Taking advantage of the azimuthal symmetry about the $z$-axis, we take advantage of the cylindrical coordinates defined by \cite{medel2024electric}
\begin{align}
k_{x} = k_{\perp} \cos \varphi \,, \quad
k_{y} = k_{\perp} \sin \varphi\ \text{ and } k_{z} = k_{z}\,, 
\end{align}
where $k_{\perp} \in [0, \infty )$ and $\varphi \in [0, 2 \pi )$. We can rewrite the velocity components(x and y) as

\begin{equation}
 v_{k_x}^s=v_{k_\perp}^s \cos\varphi, v_{k_y}^s=v_{k_\perp}^s \sin\varphi
\end{equation}
with
\begin{eqnarray}
v_{k_\perp}^s&=&  \frac{v_F k_{\perp}}{ k}-
\frac{s e B v_F k_z k_\perp}{ \hbar k^4 }\nonumber\\
\end{eqnarray}

In the next step, we change the variables from $(k_{\perp} , k_{z})$ to $(k_{x'},k_{y'} ,k_{z'} )$ by the coordinate transformation \cite{wang2023field}.

\begin{eqnarray}
k_{x}& =& k_{x'},\\
k_{y}&=&k_{y'}, \\
k_z&=&\frac{k_z'}{\sqrt{1-t^2}}-\frac{\epsilon_{\bm k'}^0}{\hbar v_F}\frac{t}{1-t^2} \nonumber\\
&=&\frac{k_z'}{\sqrt{1-t^2}}-k'\frac{t}{1-t^2}  
\end{eqnarray}
where $\epsilon_{\bm k'}^0= \hbar v_F k'\sqrt{1-t^2}$ with $k'=\sqrt{k_{x'}^2+k_{y'}^2+k_{z'}^2}$. Therefore, $k=\frac{k'-t k_{z'}}{\sqrt{1-t^2}}$, The Jacobian of the transformation is $\mathcal{J} (k' ) =  \frac{1}{\sqrt{1-t^2}} $, leading to analytical expressions for longitudinal conductivities $\sigma_{zz}$ of tilted-WSMs
\begin{widetext}
\begin{multline}
\sigma_{zz}(\omega)
=i \frac{e^2}{840 \pi^2 t^3 (1-t^2)^{9/2} \mu^2 \omega \hbar} \Bigl[420\mu^4(2t-5t^3+5t^5-4t^7+3t^9-t^{11}-2t^3\sqrt{1-t^2}+4t^5\sqrt{1-t^2}-2t^7\sqrt{1-t^2}\\
+2(1-t^2)^3(-1+t^2\sqrt{1-t^2})\tanh^{-1}t )+B^2 e^2 \hbar^2 v_F^4 t^3(91-13t^2-42t^4+140t^2\sqrt{1-t^2}-140t^4\sqrt{1-t^2})\Bigr]
\end{multline}
\end{widetext}

\noindent which reduces to the expression for the conductivity of without tilt case in the limit $t\rightarrow 0$ \cite{pellegrino2015helicons}. The effect of tilt parameter for the conductivity tensor has been calculated analytically in the literature(\cite{konye2021microscopic, ma2019planar,   das2019linear, mukherjee2018anomalous}).

\begin{equation}
\sigma_{zz}(\omega)
=i \frac{e^2}{120 \pi^2 v_F\omega \mu} (13B^2 e^2  v_F^4 
+20 \mu^4)
\end{equation}

