 \section{Algorithms for Label Encoding}
\label{appendix: Algorithms for Label Encoding}
To implement label encoding, it is crucial to convert function expressions in string form into a network structure. For this purpose, we employ the following Algorithm \ref{alg:uninet_structure}.

\begin{algorithm}[!ht]
\caption{Structure Identification for UniSymNet}
\label{alg:uninet_structure}
\begin{algorithmic}[1]
    \STATE{\bfseries Input:} Symbolic expression $expr$, dimension $d$
    \STATE{Initialize} UniSymNet's structure list $\mathcal{L}$

    \STATE $\mathcal{L} \gets \left[ \left[ \text{id} \right] \right]$ 
    % \Comment{Initial identity layer}
    \STATE $(L_{op}, L_{expr}) \gets \textsc{SymbolicDecompose}(expr)$ 
    % \Comment{Operator-expression decoupling}
    \STATE $\mathcal{L} \gets \mathcal{L} \circ L_{op}$ 
    % \Comment{$\circ$: list concatenation}

    \WHILE{$L_{op} \neq \emptyset$}
        \STATE $\mathcal{T}_{op} \gets \emptyset,\ \mathcal{T}_{expr} \gets \emptyset$ 

        % \Comment{Temporary operator/expression sets}

        \FOR{$\sigma \in L_{expr}$} 
            \IF{$\sigma$ is nested}
                \STATE $\{(\tau_{op}^{(i)}, \tau_{expr}^{(i)})\}_{i=1}^k \gets \textsc{RecursiveParse}(\sigma)$
                \STATE $\mathcal{T}_{op} \gets \mathcal{T}_{op} \cup \{\tau_{op}^{(i)}\},\ \mathcal{T}_{expr} \gets \mathcal{T}_{expr} \cup \{\tau_{expr}^{(i)}\}$
            \ELSE
                \STATE $(\tau_{op}, \tau_{expr}) \gets \textsc{SymbolicDecompose}(\sigma)$
                \STATE $\mathcal{T}_{op} \gets \mathcal{T}_{op} \cup \{\tau_{op}\},\ \mathcal{T}_{expr} \gets \mathcal{T}_{expr} \cup \{\tau_{expr}\}$
            \ENDIF
        \ENDFOR

        \STATE $\mathcal{L} \gets \mathcal{L} \circ \mathcal{T}_{op}$
        \STATE $L_{op} \gets \textsc{Flatten}(\mathcal{T}_{op}),\ L_{expr} \gets \textsc{Flatten}(\mathcal{T}_{expr})$
    \ENDWHILE

    \STATE $\mathcal{L} \gets \textsc{Prune}(\mathcal{L})$ 
    % \Comment{Remove $\emptyset$ via $\lambda x.\,x \neq \emptyset$}
    \STATE{\bfseries Output:}  $\mathcal{L}$
\end{algorithmic}
\end{algorithm}


