\subsection{Assumptions on the constraints and illustrative examples} 
\label{sec:unsafe-set} 
Recall the chance constrained optimization model \eqref{eqn:CCP},
%\begin{equation}
%    \min_{\xx \in \mathcal X} \ c(\xx) \quad \text{ s.t. } \quad  \mathbb P\left\{ g_k(\xx, \xxi) \leq 0, \ k = 1,\ldots, K  \right\} \geq 1-\alpha,
%    \label{eqn:CCP}
%\end{equation}
which we  labeled as $\CCPalpha$ in the introduction. A key ingredient in the $\CCPalpha$ model is the collection of $K$ constraints $\{ g_k(\xx,\xxi) \leq 0, k \in [K]\},$ where $K$ is a positive integer,  and   
$g_k:\mathbb{R}^m \times \R^d \rightarrow \bar{\R} , k \in [K],$ are lower semicontinuous functions specified suitably for a problem at hand. With $\xxi$ denoting an $\mathbb{R}^d$-valued  random vector modeling all the uncertain factors affecting the decision problem, 
the   constraints $\{ g_k(\xx,\xxi) \leq 0, k \in [K]\}$ typically model critical requirements  such as meeting demands in  commodity supply networks or disaster relief networks (see Examples \ref{eg:transportation}-\ref{eg:nw-design} below), or  regulatory capital requirements in insurance-reinsurance networks (eg., \citealt{blanchet2023efficient}). 
In applications where it is either infeasible or unduly expensive to ensure that the requirements $\{ g_k(\xx,\xxi) \leq 0, k \in [K]\}$ are \textit{always} satisfied, the decision-maker strives to ensure that they are met, at least, with a pre-agreed target probability level $1-\alpha \in (0,1).$ 
In line with this goal, the chance-constrained optimization model $\CCPalpha$ seeks to find a  decision from the set $\mathcal{X} \subseteq \R^m$ that minimizes the cost function $c:\mathcal{X} \rightarrow \R$ while meeting the service level agreement $P\{g_k(\xx,\xxi) \leq 0, k \in [K]\} \geq 1-\alpha.$ 

%Our first objective is to characterize the behaviour of the optimal value and optimal solution(s) of $\CCPalpha$ as the target probability level $1-\alpha$ is raised to one, and discuss the key implications stemming from the characterization.

Throughout the paper, we shall assume that the random vector $\xxi$ has a probability density supported on a closed cone $\mathcal{E} \subseteq \R^d.$ In applications, we typically have $\mathcal{E}$ as either the positive orthant $\R^d_+$ or the euclidean space $\R^d,$ the cost function $c(\xx)$ is  linear in the decision $\xx$, and the service requirements $\{ g_k(\xx,\xxi) \leq 0, k \in [K]\}$ are often specified via functions $g_k(\xx,\xxi)$ which are linear or bilinear in $\xx,\xxi.$ In more sophisticated instances, the functions $\{c,g_i:i \in [K]\}$ may be non-linear (or) may get specified by means of the value of an optimization problem; see,  for eg., \cite{yang2016distributionally,blanchet2023efficient, pena2020dc}. Without restricting to a specific functional form, our assumptions below specify requirements on the constraint functions $\{g_k:k \in [K]\}$ that bestow sufficient regularity %to bring out the desired characterizations of the optimal cost and decisions 
while allowing broader use. %For brevity, let $\mv{g}(\cdot)$  denote the vector-valued function $(g_1(\cdot),\ldots,g_K(\cdot)).$ 
We first introduce  the notion of ``safe set" $\mathcal{S}(\xx)$ for any decision $\xx$ which is helpful  towards this end.  For any $\xx \in \R^m,$ let 
\begin{align}
    \mathcal{S}(\xx) = \left\{ \zz \in \mathcal{E}: \max_{k \in [K]} g_k(\xx,\zz) \leq 0 \right\},
    \label{eq:safe-sets}
\end{align}
denote the set of scenarios $\zz$ for which the constraints $g_k(\xx,\zz) \leq 0$ hold for all $k \in [K].$ Observe that $\mathcal{S}: \R^m \rightrightarrows \R^d$ is a set-valued map. Let $\mathcal{X}^\prime := \{\xx \in \mathcal{X}: \text{ interior of } \mathcal{S}(\xx) \neq \emptyset \}$ 

\begin{definition}[\textbf{Non-vacuous set-valued mapping}]
\em 
We call a set-valued map $S: \R^m \rightrightarrows \R^d$ to be \textit{non-vacuous} for the support $\mathcal{E}$ and the decision set $\mathcal{X}$ if for every $\xx \in \mathcal{X},$ the ``unsafe set" 
$\mathcal{E} \setminus {S}(\xx)$ is (i) non-empty, and (ii) bounded away from $\{ \mv{0} \}$ for every $\xx \in \mathcal{X}^\prime.$
%whenever $\mathcal{S}(\xx)$ has a nonempty interior. 
    \label{defn:nonvacous-sets}
\end{definition}
%Equivalently, for a non-vacuous set-valued map $\mathcal{S}(\xx),$ we have that the distance $\inf\{\Vert \zz \Vert: \zz \in \mathcal{E}, \max_{k \in [K]} g_k(\xx,\zz) > 0 \} \in (0,\infty)$ whenever $\mathcal{S}(\xx)$ has  non-zero Lebesgue measure in $\R^d$.   
%for any non-zero $\xx \in \mathcal{X}$. %Note that the requirement (1) for non-vacuous sets in Definition \ref{defn:nonvacous-sets} above stipulates that no decision is entirely safe. 
%The latter requirement (2) in Definition \ref{defn:nonvacous-sets}, together with Assumption \ref{assume:constraint-functions} below, yields that scenarios $\zz$ not in the safe set are bounded away from the origin.

\noindent Equipped with these notions, we are now ready to introduce the regularity required for our analysis.

\subsubsection{Homogeneous safe-set model.}
\label{sec:hom-safeset}
We first present the simpler model based on homogeneity here, before moving to the more general assumption in Section \ref{sec:nonhom-safeset}. 
%under which the set-valued map $\mathcal{S}$ introduced in \eqref{eq:safe-sets} is homogeneous. 
\begin{assumption}
\em 
 %   The set $\mathcal{X}$ and the collection of lower semicontinuous constraint functions $\{g_k : k \in [K]\}$ satisfy the following condition: 
 There exists a constant $r \neq 0$ such that  for any $\xx \in \mathcal{X}$ and $t > 1,$ we have $t^r\xx \in \mathcal{X}$ and $\mathcal{S}(t^r \xx) = t\mathcal{S}(\xx).$ Further,  the map $\mathcal{S},$ defined in \eqref{eq:safe-sets}, is continuous on $\mathcal{X}$ and 
        non-vacuous  for the support $\mathcal{E}$ and decision set $\mathcal{X}.$
    \label{assume:hom-safe-set}
\end{assumption}

Assumption \ref{assume:hom-safe-set} allows for an easy interpretation  as follows: Given any $\xx \in \R^m$ and $t > 1,$ suppose that a decision-maker wishes to identify a decision $\xx^\prime$ that makes $t\mathcal{S}(\xx)$ scenarios to be safe (that is, $\mathcal{S}(\xx^\prime) = t\mathcal{S}(\xx)$). Satisfaction of Assumption \ref{assume:hom-safe-set} means that they can achieve this by choosing $\xx^\prime = t^r\xx.$ In other words, $\mathcal{S}(\xx^\prime) = \mathcal{S}(t^r\xx) = t\mathcal{S}(\xx).$ As it will become evident from the first main result (Theorem \ref{thm:solution_convergence}) in Section \ref{sec:Asymptotics},  %satisfaction of Definition \ref{defn:nonvacous-sets} by
non-vacuousness of the
safe-sets $\mathcal{S}(\xx)$ will ensure that the value of $\CCPalpha$ in \eqref{eqn:CCP} is not trivially zero or infinite. 

\begin{example}[Joint capacity sizing and probabilistic transportation]\label{eg:routing}
\em 
Consider the  formulation, %with joint probabilistic constraints, 
    \begin{align*}
        \min_{\xx,\yy \geq \mv{0}} \sum_{i=1}^M c_i  x_i  + \sum_{i=1}^M\sum_{j=1}^N d_{ij} y_{ij}   \quad \text{s.t.} \ \ \Prob\left\{ \sum_{i:(i,j) \in E} y_{ij}  \geq \xi_j, \  \forall j \in [N] \right\} \geq 1-\alpha,\ \ \sum_{j:(i,j) \in E} y_{ij}  \leq x_i \ \forall i \in [M],
    \end{align*}
which includes the classical transportation problem as an instance with applications in commodity distribution and emergency response; see, eg., \cite{luedtke2010integer,beraldi2004designing}. In this joint capacity sizing and transportation problem,  we have $M$ factories producing a single commodity, $N$ distribution centers, and a distribution center $j \in [N]$ connected with a factory $i \in [M]$ only if $(i,j)$ lies in the edge set $E \subseteq [M] \times [N].$ The goal is to identify  factory supply capacities $\xx = (x_1,\ldots,x_M)$ and a transportation plan $\yy = (y_{ij}: (i,j) \in E)$ jointly such that the cumulative capacity allocation and transportation costs 
%, captured by $\sum_{i=1}^M c_i  x_i  + \sum_{i=1}^M\sum_{j=1}^N d_{ij} y_{ij},$ 
is minimized while ensuring  the factories are resourced sufficiently to meet the demand  $\xxi$ at the distribution centers with  probability $1-\alpha.$ 

To verify Assumption \ref{assume:hom-safe-set},
observe that $\mathcal{X} := \{(\xx,\yy) \in \R^M_+ \times \R^{\vert E \vert}_+: \sum_{j: (i,j) \in E} y_{ij} \leq x_i \ \forall i \in [M]\}$ is a cone.  Further, $t \mathcal{S}(\xx,\yy) = \{ t\zz \geq \mv{0} : \sum_{i: (i,j) \in E} y_{ij} 
 \geq z_j \  \forall j \in [N]\} = \{ \zz^\prime \geq \mv{0}: \sum_{i: (i,j) \in E} t y_{ij} 
 \geq z_j^\prime \  \forall j \in [N]\} = \mathcal{S}(t\xx,t\yy).$ Since the graph of the map $\mathcal{S}$ given by 
\[ \left\{(\xx,\yy,\zz) \in \R^M_+ \times \R^{\vert E \vert}_+ \times \R^d_+ : \sum_{i: (i,j) \in E} y_{ij} 
 \geq z_j \  \forall j \in [N], \sum_{j: (i,j) \in E} y_{ij} \leq x_i \ \forall i \in [M] \right\} \] is polyhedral,  the map $\mathcal{S}(\cdot)$ is continuous (\citealt[Eg. 9.35]{rockafellar2009variational}). Further, note that whenever $\mv{0} < \zz^\prime = (z_1^\prime, \ldots,z_d^\prime) \in \mathcal{S}(\xx,\yy)$ for  $(\xx,\yy) \in \mathcal{X},$ we have $(0,\ldots, 0, z_i^\prime, 0, \ldots, 0) \in \mathcal{S}(\xx,\yy),$ for any $i \leq d.$ As a result, $\{\zz \in \R^d_+: \Vert \zz \Vert_\infty \leq \min_{i \leq d} z_i^\prime\} \subseteq \mathcal{S}(\xx,\yy),$ and due to the convexity of $\mathcal{S}(\cdot),$ we have that the map  $\mathcal{S}(\cdot)$ is non-vacuous for the support $\mathcal{E} = \R^d_+$ and decision set $\mathcal{X}.$ \hfill$\Box$ 

%This completes the verification of  all the requirements of Assumption \ref{assume:hom-safe-set}   with $r = 1.$

\label{eg:transportation}
\end{example}

\noindent 
Note that the reasoning in Eg. \ref{eg:transportation} does not rely  on the network structure, and Assumption \ref{assume:hom-safe-set} can be verified to hold with $r=1$ more broadly for linear chance constraints of the form $\Prob\left\{ A\mv{x} \geq \xxi \right\} \geq 1-\alpha$ featuring  right-hand uncertainty.


%the observation that  Assumption \ref{assume:hom-safe-set} holds with $r = 1$ is satisfied more generally for a broader variety of chance constraints of the form  $\Prob\left\{ A\mv{x} \geq \xxi \right\} \geq 1-\alpha$ featuring  right hand uncertainty.


\begin{example}[Network design]
\label{eg:nw-design}
\em 
    Consider the problem 
    \begin{align}
        \min_{\xx} \mv{c}_{_V}^\intercal \xx_{_V} + \mv{c}_{_E}^\intercal \xx_{_E}  \quad \text{s.t.} \quad & P\left( \exists \, \mv{f}  : \xx_{_V} - A\mv{f} \geq \xxi, \mv{0} \leq \mv{f} \leq \mv{x}_{_E} \right) \geq 1-\alpha, \label{eq:nw-flow}\\
        &\sum_{i \in V} \mathbf{1}(x_{i,V} > 0) = N, \ \xx_{_V} \geq \mv{0}, \xx_{_E} \geq \mv{0}, \nonumber
    \end{align}
    in which a network designer aims to locate $N$ outposts at suitable vertices of a given network, equip those vertices with supply capacities $\xx_{_V}$ and arcs with flow capacities $\xx_{_E}$ such that the following requirement is met: The stochastic demands arising in different nodes of the network, captured by the random vector $\xxi,$ should be met with a feasible flow with probability at least $1-\alpha.$ Here  $A$ is the node-arc incidence matrix. Network design formulations of this nature arise in disaster relief   \citep{disaster_response} and emergency medical response \citep{boutilier_chan}; see also \cite{atamturk}. 
   If we take $L(\xx,\zz) = \inf\{s \geq 0, \mv{f} : \xx_{_V} - A\mv{f} \geq \zz, s\mv{1} \geq \mv{f}, \mv{0} \leq \mv{f} \leq \mv{x}_{_E}\},$ then note that $L(\xx,\zz)$ is finite if and only if there is a feasible flow. Further, $L(\xx,\xxi) \leq \mv{1}^\intercal \xx_E$ if $L(\xx,\xxi)$ is finite. Therefore, the chance constraint in \eqref{eq:nw-flow} can be equivalently written as $P\{L(\xx,\xxi) - \mv{1}^\intercal \xx_{_E} \leq 0\} \geq 1-\alpha.$ Note that for any $\xx = (\xx_{_V},\xx_{_E}) \in \mathcal{X}= \{(\xx_{V},\xx_{_E}) \geq \mv{0}: \sum_{i \in V} \mathbf{1}(x_{i,V} > 0)= N\}$  and $t > 1,$ we have $t\xx \in \mathcal{X}$ and  $L(t\xx,t\zz)=tL(\xx,\zz).$  An immediate implication of this homogeneity is $\mathcal{S}(t\xx) = t\mathcal{S}(\xx),$ as
   \begin{align*}
   \mathcal{S}(t\xx) &= \{\zz \in \mathcal{E}: L(t\xx,\zz) - t\mathbf{1}^\intercal \xx_{_E} \leq 0\} = \{t\zz^\prime \in \mathcal{E}: L(t\xx,t\zz^\prime) - t\mathbf{1}^\intercal \xx_{_E} \leq 0\}\\
   &= t\{ \zz^\prime \in \mathcal{E}: L(\xx,\zz^\prime) 
 - \mathbf{1}^\intercal \xx_{_E} \leq 0\} = t\mathcal{S}(\xx).
 \end{align*}
   Since the graph of the map $\mathcal{S}(\cdot)$ given by $\{(\xx,\zz) \geq \mv{0}: \xx = (\xx_{_V}, \xx_{_E}), \xx_{_V} - A\mv{f} \geq \zz, \mv{0} \leq \mv{f} \leq \mv{x}_{_E}\}$ is polyhedral, the map $\mathcal{S}(\cdot)$ is continuous (see \citealt[Eg. 9.35]{rockafellar2009variational}). %Note that whenever $\mv{0} < \zz^\prime = (z_1^\prime, \ldots,z_d^\prime) \in \mathcal{S}(\xx),$ we have $(0,\ldots, 0, z_i^\prime, 0, \ldots, 0) \in \mathcal{S}(\xx),$ for any $i \leq d.$ As a result, $\{\zz \in \R^d_+: \Vert \zz \Vert_\infty \leq \min_{i \leq d} z_i^\prime\} \subseteq \mathcal{S}(\xx),$ due to the convexity of $\mathcal{S}(\xx).$ As a result, $\mathcal{S}(\cdot)$ is non-vacuous for the support $\mathcal{E}$ and the  decision set $\mathcal{X}.$   
  % Moreover, $\sum_{i \in V} \mathbf{1}(tx_{i,V} > 0) = N$ whenever $\sum_{i \in V} \mathbf{1}(x_{i,V} > 0) = N$ and $t > 1.$ 
   Exactly following the same reason in  Example \ref{eg:transportation}, we have $\mathcal{S}(\cdot)$ to be non-vacuous  for the support $\mathcal{E}$ and the  decision set $\mathcal{X}= \{(\xx_{V},\xx_{_E}) \geq \mv{0}: \sum_{i \in V} \mathbf{1}(x_{i,V} > 0)= N\}.$ Therefore  
   Assumption \ref{assume:hom-safe-set} is satisfied with $r = 1.$   
   \hfill$\Box$
\end{example}

\subsubsection{Non-homogeneous safe-set model.} 
\label{sec:nonhom-safeset} 
We next present an alternative requirement on the constraint functions that holds more broadly than the homogeneous case in Section \ref{sec:hom-safeset}. 

\begin{assumption}
    \label{assume:non-hom-safeset}
    There exist constants $r \neq 0,\, \rho \geq 0,$ and  a  function $g^\ast:\R^m \times \R^d \rightarrow \bar{\R}$ such that the following are satisfied: %for any sequence $\{\xx_n\} \subset \R^m$ satisfying $\xx_n \rightarrow \xx$:
\begin{itemize}
\item[i)] for any $\xx \in \mathcal{X}$ and $t > 1,$ we have $t^r\xx \in \mathcal{X};$
 \item[ii)] for any sequence $(\xx_n,\zz_n) \rightarrow (\xx,\zz),$ 
 \begin{align}
 \liminf_n \frac{\max_{k \in [K]} g_k(n^r\xx_n,n\zz_n)}{n^\rho} \geq g^\ast(\xx,\zz); 
     \label{eq:epi-liminf}
 \end{align}
 \item[iii)] given any sequence $\xx_n \rightarrow \xx$  and $ \zz \in \R^d,$ we have  \begin{align}
     \limsup_n \frac{ \max_{k \in [K]} g_k(n^r\xx_n,n\zz_n)}{n^\rho} \leq g^\ast(\xx,\zz)
     \label{eq:epi-limsup}
 \end{align}  for some sequence $\zz_n \rightarrow \zz;$  
 \item[(iv)] the set-valued  map $\mathcal{S}^\ast: \R^m \rightrightarrows \R^d$ defined by  $\mathcal{S}^\ast(\xx) = \{\zz \in \mathcal{E}: g^\ast(\xx,\zz) \leq 0\}$  is non-vacuous  for the support $\mathcal{E}$ and the decision set $\mathcal{X}.$
% \item[iv)] for any $\xx\in\mathcal X,$    the set $\mathcal{S}^\ast(\xx) := \{\zz \in \mathcal{E}: g^\ast(\xx,\zz) \leq 0 \} \neq \mathcal{E}$; and
% \item[v)] there exists $\xx \in \mathcal{X}$ such that $\mathcal{S}^\ast(\xx) \neq \emptyset$.
\end{itemize}
\end{assumption}

Observe that \eqref{eq:epi-liminf}-\eqref{eq:epi-limsup} are readily satisfied if $g_k(n^r\xx_n, n\zz_n)/n^{\rho} \rightarrow g_k^\ast(\xx,\zz)$
%\begin{align*}
%  \frac{g_k(n^r\xx_n, n\zz_n)}{n^\rho} \rightarrow g_k^\ast(\xx,\zz)  
%   \label{eq:cont-conv}
%\end{align*}
for any sequence $(\xx_n,\zz_n) \rightarrow (\xx,\zz).$ %As is evident from  \eqref{eq:epi-limsup} above, the convergence in Assumption \ref{assume:constraint-functions}(b) imposes only a weaker requirement than \eqref{eq:cont-conv}. 
The weaker notion of convergence in \eqref{eq:epi-liminf} - \eqref{eq:epi-limsup} is related to the well-known notion of epi-convergence in the optimization literature \cite[Prop. 7.2]{rockafellar2009variational}. Specifically, if we let $g_{k,n}(\xx,\zz) = n^{-\rho} g_k(n^r\xx,n\zz)$ as suitably scaled versions of the constraint functions, then \eqref{eq:epi-liminf} - \eqref{eq:epi-limsup} are equivalent to saying that the sequence of  functions $\max_k g_{k,n}(\xx_n,\cdot),$ are epi-converging to $g^\ast(\xx,\cdot),$ whenever $\xx_n\to \xx$.
%In other words, we have that the epigraph of the  functions $\max g_n(\xx_n, \cdot)$ converges to the epigraph of $g^\ast(\xx,\cdot)$.  
%As we shall see in the examples below, the weaker notion in Conditions (a) - (b) is key to expanding the scope of our results to important applications where certain operational decisions can be made after observing the realization of the random vector $\xxi.$ 
%Besides the satisfaction of Assumption \ref{assume:constraint-functions}(b) under continuous convergence of $g_k,$ 
Another sufficient condition for \eqref{eq:epi-liminf} - 
 \eqref{eq:epi-limsup} is the epi-convergence of $g_{k,n}(\xx_n, \cdot)$ when  
% $g_k(n^r\xx,n\zz_n)/n^\rho$ when 
$g_k(\xx,\cdot)$ is convex for every $\xx$ and $k$ \cite[Prop. 7.48]{rockafellar2009variational}. 



%It is instructive to note that if for each $\xx$, $g_k(\xx,\cdot)$ were convex in $\zz$ for $i=1,\ldots, K$, then the epi-convergence of each $g_k^n$ to a limit would imply \eqref{eq:epi-liminf} - \eqref{eq:epi-limsup} 
%(see \cite{rockafellar2009variational}, Proposition 7.48). %Conditions (iv) - (v) in  Assumption \ref{assume:constraint-functions}(b) ensure that the limit  $g^\ast,$ is non-vacuous.  %As we shall see in Examples~\ref{eg:routing} - \ref{eg:nw-design} below, it is typically easy to exhibit the limiting function $g^\ast$ as identically zero if the  scaling constants $r,\rho$ are not appropriately chosen. Conditions (iv) - (v) ensure that the scaling constants $r,\rho$ are chosen well enough that they do not lead to such degeneracy which is not conducive for further analysis. 



\begin{example}[Linear portfolio selection]\label{eg:portfolio_opt}
\em 
Consider the problem, 
\begin{equation*}%\label{eqn:Portfolio_Opt}
       \min_{\xx \in \R^d: \xx \neq \mv{0} } \ c(\xx) \ \quad  \text{ s.t } \quad \ \Prob\left\{ \xx^\intercal \mv{\xi} + \mu_0 (1-\mv{1}^\intercal \xx)  \geq R \right\} \geq 1-\alpha, \ \mv{0} \leq \xx \leq \mv{1},
    \end{equation*}
which aims to select a minimum cost portfolio weight vector $\xx$ whose resulting portfolio return is above a prescribed minimal level  $R > 0$ with probability at least $1-\alpha;$ see, example, \cite{bonami2009exact,pagnoncelli2009computational}. Here $\mu_0$ is the risk-free return and $\xxi$ is the random vector modeling returns of $d$ risky assets. One may take $-c(\xx) = \xx^\intercal E[\xxi] -\mu_0(1-\mv{1}^\intercal \xx)$ signifying average portfolio return, as taken in \cite{pagnoncelli2009computational}, (or) combine it with a  risk measure $c(\xx) = (\xx^\intercal \text{Cov}[\xxi] \xx)^{1/2}$ signifying portfolio variance as in \cite{bonami2009exact}. Note that $g(\xx,\zz) = R - \xx^\intercal \xxi - \mu_0 (1-\mv{1}^\intercal \xx)$ satisfies 
\begin{align*}
    g(n^{-1}\xx_n,n\zz_n) = R - \left(\frac{\xx_n}{n}\right)^\intercal n\zz_n - \mu_0\left( 1- \mv{1}^\intercal \left(\frac{\xx_n}{n}\right)\right) \rightarrow R -\xx^\intercal \zz - \mu_0.
\end{align*}
whenever $(\xx_n,\zz_n) \rightarrow (\xx,\zz).$ As a result, Assumption \ref{assume:non-hom-safeset} holds with $r = -1, \rho = 0,$ and $g^\ast(\xx,\zz) = R - \xx^\intercal \zz - \mu_0.$ The resulting $\mathcal{S}^\ast(\xx) = \{\zz \in \R^d: R - \xx^\intercal \zz - \mu_0 \leq 0\}$ is non-vacuous for the support $\mathcal{E} = \R^d$ and decision set $\mathcal{X} = \{ \xx \in \R^d: \mv{0} \leq \xx \leq \mv{1}, \xx \neq \mv{0}\}$ when  $R < \mu_0.$ \hfill $\Box$
\end{example}

Note that if we had alternatively taken the scaling constants $r,\rho$ in \eqref{eq:epi-liminf} - \eqref{eq:epi-limsup} to be $r = -1,\rho > 0$ in Example \ref{eg:portfolio_opt}, we would obtain $g(n^{-1}\xx_n, n\zz_n)/n^\rho \rightarrow g^\ast(\xx,\zz) = 0$ which would lead to  vacuous $\mathcal{S}^\ast(\xx) = \R^d.$  On the other hand, if we had  taken $r = 1,\rho=2,$ we would obtain $g(n\xx_n, n\zz_n)/n^2 \rightarrow g^\ast(\xx,\zz) = -\xx^\intercal \zz$ which would again lead to a vacuous $\mathcal{S}^\ast(\xx) = \{\zz \in \R^d: -\xx^\intercal \zz \leq 0\}.$ Proposition \ref{prop:unique_r_rho} below asserts that an appropriate choice of scaling constants $r,\rho$ in Assumption \ref{assume:non-hom-safeset} that renders the resulting $\mathcal{S}^\ast(\xx)$ to be non-vacuous is unique. 

\begin{proposition}
    \label{prop:unique_r_rho}
    \em 
    If the collection of constants $(r,\rho)$ for which 
    Conditions (ii) - (iv) of Assumption \ref{assume:non-hom-safeset} are satisfied is non-empty, then it is unique.
\end{proposition}

\subsection{Assumptions on the cost  function}
We next introduce a mild structure  on the cost  $c(\cdot),$ which can be readily verified in the examples in Section \ref{sec:unsafe-set}. To state the assumption, recall the definition 
$\mathcal{X}^\prime := \{\xx \in \mathcal{X}:\,\text{interior of } \mathcal{S}(\xx) \neq \emptyset \}$ and the constant $r$ for which the constraint functions $\{g_k: k \in [K]\}$ satisfy Assumption  \ref{assume:hom-safe-set} or \ref{assume:non-hom-safeset}. 


\begin{assumption}
\label{assume:cost}
\em 
The cost function $c:\mathcal{X} \rightarrow \R$ is positively homogeneous, that is, $c(t\xx) = tc(\xx),$ for every $t > 0$ and $\xx \in \mathcal{X}.$ Further, the mapping  $t \mapsto c(t^r\xx)$ is strictly increasing for every $\xx \in \mathcal{X}^\prime.$
\end{assumption}

Note that if $c$ is positively  homogeneous with degree $s > 0,$ then one can simply take $c^{1/s}$ as the cost function satisfying Assumption \ref{assume:cost}. The results also extend to the case of approximately homogeneous costs  where $ c(t^r \xx) \sim  t^r c(\xx),$ as $t \rightarrow \infty,$ uniformly over $\xx$ in compact subsets of $\R^m$ not containing the origin. %Here the value of $r$ is specified as in Assumptions \ref{assume:hom-safe-set}-\ref{assume:non-hom-safeset}. 
For the ease of exposition, we limit the treatment to Assumption \ref{assume:cost}.




\subsection{Assumptions on the probability distribution of $\xxi$}
\label{sec:Xi_Assumptions}
We assume that the random vector $\xxi$ satisfies either Assumption $(\mathscr  L)$ or Assumption $(\mathscr  H)$ below, with the former corresponding to multivariate light-tailed distributions and the latter capturing multivariate heavy-tailed distributions. For $i \in [d],$ let $f_{\xxi}:\mathcal{E} \rightarrow \R$ denote the probability density of $\xxi,$  $\bar F_i(z) := P(\xi_i >z)$ denote the complementary cumulative distribution function (CDF) of $\xi_i.$  Let $\bar{F}(z) := \max_{i \in [d]} \bar{F}_i(z)$ capture the marginal distribution with the heaviest tail. %and $\lambda(z) := -\log \bar F(z),$. %$z \in R.$
The following definition is useful for introducing Assumptions $(\mathscr{L})$ and $(\mathscr{H}).$

\begin{definition}
\em 
A function $f:\R_+ \rightarrow \R_+$ is
said to be \textit{regularly varying} with index $\rho \in \mathbb{R}$ if $f(tx)/f(t) \rightarrow x^\rho$ for every $x > 0.$
\label{defn:regularly-varying}
\end{definition}
If $f$ is regularly varying with index $\rho,$ we abbreviate this as $f \in \RV(\rho).$ Regularly varying functions offer a systematic and general approach for studying functions with polynomial growth/decay rates, and have served as a fundamental tool for modeling and studying distribution tails: see, example, \cite{feller2008introduction,deHaan, Resnick}.


\begin{assumption*}[$\boldsymbol{\mathscr  L}$] 
\em 
\textbf{[Lighter-tailed distributions]} The  joint probability density $f_{\xxi}$ admits the following representation uniformly over $\zz$ in compact subsets of $\mathcal{E}$ not containing the origin:
\begin{align*}
    -\log f_{\xxi}(t\zz) \sim \varphi^\ast(\zz) {\lambda}(t), \quad \text{ as } t \rightarrow \infty,
\end{align*}
for a positive function $\varphi^\ast: \mathcal{E} \rightarrow \R_{++},$ $\lambda \in \RV(\gamma),$ and $\gamma > 0.$
\end{assumption*}

\begin{assumption*}[$\boldsymbol{\mathscr  H}$] 
  \em
  \textbf{[Heavier-tailed distributions]} 
The  joint probability density $f_{\xxi}$ admits the following representation uniformly over $\zz$ in compact subsets of $\mathcal{E}$ not containing the origin:
\begin{align*}
      f_{\xxi}(t\zz) \sim \varphi^\ast(\zz)t^{-d}\lambda(t), \quad \text{ as } t \rightarrow \infty,
\end{align*}
%\begin{align*}
%      f_{\xxi}(t\zz) \sim \varphi^\ast(\zz){t^{-d}\bar{F}(t)}, \quad \text{ as } t \rightarrow \infty,
%\end{align*}
for a positive function $\varphi^\ast: \mathcal{E} \rightarrow \R_{++},$  $\lambda \in \RV(-\gamma),$ and $\gamma > 0.$
\end{assumption*} 
\noindent 
Lemma \ref{lem:marginals-light}-\ref{lem:marginals-heavy} below characterize  the marginal distributions of $\xxi$ under Assumptions ($\mathscr{L}$) and ($\mathscr{H}$).

\begin{lemma}[\textbf{Marginal distributions under Assumption $\boldsymbol{(\mathscr{L})}$}]
\label{lem:marginals-light}
Under Assumption $(\mathscr L),$  
\begin{itemize}
    \item[a)] the complementary CDFs possess an exponential decay rate as in $\bar{F}_i(tz_i) = \exp\{-c_i z_i^\gamma \lambda(t)[1+o(1)]\}$ as $t \rightarrow \infty,$ where the positive constants $c_i = \inf\{\varphi^\ast(\zz): \zz \in \mathcal{E}, z_i \geq 1\}$ for  $i \in [d];$  
    \item[b)] the heaviest tail $\bar{F}(tz) = \exp\{-\min_{i \in [d]} c_i \, z^\gamma \lambda(t)[1+o(1)]\};$ and  
    \item[b)]  consequently, one could have taken $\lambda(t) = -\log \bar{F}(t)$ in Assumption ($\mathscr L$)  without  loss of generality; in this case we will have $\min_{i \in [d]} c_i = 1.$
\end{itemize}
\end{lemma}

\begin{lemma}[\textbf{Marginal distributions under Assumption $\boldsymbol{(\mathscr{H})}$}]
\label{lem:marginals-heavy}
Under Assumption $(\mathscr H),$ 
\begin{itemize}
    \item[a)] the complementary CDFs possess a polynomial decay rate as in $\bar{F}_i(tz_i) = c_i z_i^{-\gamma} \lambda (t)[1+o(1)]$ as $t \rightarrow \infty,$ where the positive constants $c_i = \int_{z_i > 1} \varphi^\ast(\zz)d\zz$ for  $i \in [d];$   
    \item[b)] the heaviest tail $\bar{F}(tz) = \max_{i \in [d]} c_i \, z^{-\gamma} \lambda(t) [1 + o(1)]; $ and 
    \item[b)]  consequently, one could have taken $\lambda(t) = \bar{F}(t)$ in Assumption ($\mathscr H$)  without  loss of generality; in this case we will have $\max_{i \in [d]} c_i = 1.$ 
\end{itemize}

\end{lemma}
