\section{Scaling of  optimal value and solution in the high reliability regime}\label{sec:Asymptotics} 
\subsection{Large deviations characterizations for the probability of constraint violation}
In order to understand the behavior of optimal value and  solutions of $\CCPalpha,$ we first  derive novel characterizations of the probability of constraint violation, $P(\max_{k \in [K]}g_k(\xx,\xxi) > 0),$ under the assumptions introduced in Section \ref{sec:Modelling Assumptions}. To state the results governed by the cases in Assumption \ref{assume:hom-safe-set}-\ref{assume:non-hom-safeset} in a unified manner,   we take throughout the paper,
\begin{align*}
    g^\ast(\xx,\zz) = \max_{k \in [K]} g_k(\xx,\zz)  \quad \text{ if Assumption \ref{assume:hom-safe-set} is satisfied.}
 %   \label{eq:g-defn-assump-1a}
\end{align*}



%Having introduced the underlying assumptions, we are now ready to characterize the behavior of the optimal value and optimal solution(s) of $\CCPalpha$ in the high reliability regime where the target probability level $1-\alpha$ is raised to one. 

%Let $\mathcal X_{\alpha}^*$ denote the set of optimal solutions of ${\tt CCP}(\alpha)$. %Let $g = \lambda^{\leftarrow}$ and $s=\bar F^{\leftarrow}$ denote the inverse functions of $\lambda$ and $\bar F$ as defined in Section~\ref{sec:Xi_Assumptions}. Define
%The following characterizations of the probability of constraint violation, $P(\max_{k \in [K]}g_k(\xx,\xxi) > 0),$ become useful as a tool for understanding the behavior of optimal value and  solutions of $\CCPalpha.$
\begin{proposition}
\label{prop:prob-convergence_LT}
Under Assumption $(\mathscr L)$ and either of Assumptions \ref{assume:hom-safe-set} \underline{or}  \ref{assume:non-hom-safeset}, we have the following convergence,   as $t \rightarrow \infty,$ uniformly over $\xx$ in compact subsets of $\mathcal{X} \setminus \{\mv{0}\}$:
 \begin{align*}
     \log \Prob\left(\max_{k \in [K]} g_k(t^r\xx,\xxi) > 0 \right) \sim -G_0(\xx)\lambda(t),  
 \end{align*}
where $G_0(\xx) = \inf\{\varphi^\ast(\zz): g^\ast(\xx,\zz) \geq 0\}.$
\end{proposition}



\begin{proposition}
\label{prop:prob-convergence_HT}
Under Assumption $(\mathscr H)$ and either of Assumptions \ref{assume:hom-safe-set} \underline{or}  \ref{assume:non-hom-safeset}, we have the following convergence,   as $t \rightarrow \infty,$ uniformly over $\xx$ in compact subsets of $\mathcal{X} \setminus \{\mv{0}\}$:
 \begin{align*}
       \Prob\left(\max_{k \in [K]} g_k(t^r\xx,\xxi) > 0 \right) \sim G_0(\xx) \lambda(t) ,  
 \end{align*}
where $G_0(\xx) =\int_{g^*(\xx,\zz)\geq 0 } \varphi^*(\zz) d\zz.$
\end{proposition}

A well-known example of  explicit characterizations of the constraint violation probability, similar to those in Propositions \ref{prop:prob-convergence_LT} - \ref{prop:prob-convergence_HT}, is from the setting of linear  chance constraint, $g(\xx,\xxi) = v - \xxi^\intercal \xx \leq 0,$ under multivariate normal distribution $\mathcal{N}(\mv{\mu},\Sigma)$ for $\xxi.$ Here take $v$ to be a given constant, $\mv{\mu} \in \R^d,$ and $\Sigma$ is a positive definite covariance matrix.  Since $g(\xx,\xxi) \sim \mathcal{N}(\mv{\mu}^\intercal \xx, \xx^\intercal \Sigma \xx)$ in this instance, we readily have $\Prob(g(\xx,\xxi) >  0)) = \bar{\Phi}\left( (v - \mv{\mu}^\intercal \xx))/\sqrt{\xx^\intercal \Sigma \xx}\right),$ where $\bar{\Phi}(\cdot)$ is the complementary CDF of the standard normal distribution. Due to this explicit expression, the chance constraint $\{\xx: \Prob(g(\xx,\xxi) \leq 0) \geq 1-\alpha \}$ reduces to the deterministic equivalent $\{\xx: v - \mv{\mu}^\intercal \xx + \bar{\Phi}^{-1}(\alpha)\sqrt{\xx^\intercal \Sigma \xx} \leq 0 \}$ in this case. Such deterministic equivalents, while pivotal in the earlier literature, are typically difficult to obtain beyond stylized examples. The probability characterizations in Propositions \ref{prop:prob-convergence_LT} - \ref{prop:prob-convergence_HT} above can be viewed as offering a pathway towards such deterministic characterizations much more broadly, with the caveat that the resulting deterministic constraints set we introduce next becoming equivalent to the chance constrained set only asymptotically. 


%\subsection{The main result on the scaling of optimal cost and decision}
\subsection{Main result 1: Scaling of the optimal cost and solutions of $\CCPalpha$}
To ease the notational burden, define
\begin{equation}\label{eqn:scaling}
 s_{\alpha} := 
    \bar F^{-1}(\alpha)  
\end{equation}
where $\bar{F}^{-1}$ is the inverse function of $\bar F := \max_{i \in [d]} \bar{F}_i.$ In line with the notation in Lemma \ref{lem:marginals-light}-\ref{lem:marginals-heavy} and  Propositions \ref{prop:prob-convergence_LT} - \ref{prop:prob-convergence_HT}, assign for any $\xx \in \mathcal{X},$ 
\begin{align}
\label{eqn:I_star_limit}
 I(\xx) := 
\begin{cases}
\left[\inf\{\varphi^*(\zz) : g^\ast(\xx,\zz) \geq 0\}\right]^{-1} \min_{i \in [d]} c_i \quad \quad \quad  \ \ & \text{ if } \xxi \text{ satisfies Assumption~(${\mathscr L}$)}\\
[\max_{i \in [d]} c_i]^{-1}\int_{g^\ast(\xx,\zz) \geq 0}  \varphi^*(\zz) d\zz  \quad & \text{ if } \xxi \text{ satisfies Assumption~(${\mathscr H}$)}.  
\end{cases}
 \end{align}
 %Then the main result of this paper can be stated as follows.\\ 

\begin{theorem}
%[\textbf{Scaling of the optimal value and solution of $\CCPalpha$}]
\label{thm:solution_convergence}
%\em 
   Suppose that the constraint functions satisfy either Assumption \ref{assume:hom-safe-set} \underline{\tt or} Assumption \ref{assume:non-hom-safeset}, the cost function satisfies Assumption \ref{assume:cost}, and $\xxi$ satisfies Assumption ($\mathscr{L}$)  or ($\mathscr{H}$). Then, as $\alpha \rightarrow 0,$
\begin{itemize}
    \item[a)] the optimal value of 
$\CCPalpha$, call it  $v_\alpha^*,$ satisfies
    %\begin{equation}\label{eqn:value_asymptotic}
     $v_\alpha^* \sim v^* s_\alpha^{r},$
     %\end{equation}
     where $v^\ast$ is the optimal value of the deterministic optimization problem $\Dapprox$
    below in \eqref{eq:d-approx}:
    \begin{equation}
    \label{eq:d-approx}
    \Dapprox: \qquad\qquad \min_{\xx \in \mathcal{X}} \ c(\xx) \quad \textnormal{ s.t. } \quad   I(\xx) \leq 1. \qquad\qquad\qquad\qquad   
    \end{equation}
    \item[b)] any optimal solution of $\CCPalpha,$ call it $\xx_\alpha^\ast,$ satisfies  $ d(s_\alpha^{-r}\xx_{\alpha}^
    \ast, \mathcal{X}^\ast) \rightarrow 0,$ where 
    $\mathcal{X}^\ast$ denotes the set of optimal solutions for $\Dapprox.$  In particular, if $\Dapprox$ has a unique solution $\xx^\ast,$  then
    \begin{equation}
    \label{eqn:solution_convergence}
         \xx_\alpha^* \sim  \xx^* s_\alpha^{r}, \quad \text{ as } \alpha \to 0.
    \end{equation}
\end{itemize}   
\end{theorem}

Example \ref{eg:Multiple_linear_CCs} below contextualizes the application of Theorem \ref{thm:solution_convergence} to a specific setting. 
\begin{example}
    \label{eg:Multiple_linear_CCs}
    \em 
    Consider the linear chance constraint $P\{ T_k(\xx)\xxi \leq u_k, k \in [K] \} \geq 1 - \alpha,$ with $\xxi$ being elliptically distributed as in Example \ref{eg:Elliptical_densities}, $T_k(\xx) = \xx^\intercal B_k,$ matrices $B_k \in \R^{m \times d},$ and $u_k \in \R,$ for $k \in [K].$ Here the constraint functions $g_k(\xx,\zz) = \xx^\intercal B_k \zz - u_k,$ for $ k \in [K],$  readily satisfy Assumption \ref{assume:hom-safe-set} with $r = -1.$ If the generator  $h(\cdot)$ for the elliptical distribution satisfies $h(t) = \exp(-c^\prime t^{\gamma/2}(1+ o(1)),$ we have from Example \ref{eg:Elliptical_densities} that Assumption $(\mathscr L)$ is satisfied with $\lambda(t) = t^{\gamma}$ and $\varphi^\ast(\zz) = c^\prime (\zz^\intercal \Sigma^{-1} \zz)^{\gamma/2}.$ Let $\sigma_i = \Sigma_{ii}^{1/2}$ for $i \in [d].$ Then from Lemma \ref{lem:marginals-light}(b), we have $s_\alpha \sim \sigma_{\max} [(\ln 1/\alpha)/c^\prime]^{1/\gamma},$ as $\alpha \rightarrow 0,$   
    %since the marginal distributions are also elliptically distributed with complementary CDF $\bar{F}_i(x) = \exp(-c^\prime (x/\sigma_i)^\gamma (1+o(1) )$ as $x \rightarrow \infty$ (see \citealt[Sec 1.2.4]{frahm2004generalized}),
    %\[s_\alpha = \bar{F}^{-1}(\alpha) = \inf \left\{x: \max_{i \in [d]} \exp(-c^\prime (x/\sigma_i)^{\gamma}(1+o(1))) \leq \alpha \right\} =  \sigma_{\max} \left(\frac{\ln 1/\alpha}{c^\prime}\right)^{1/\gamma} (1 + o(1)),\]
    where $\sigma_{\max} := \max_{i \in [d]} \sigma_i$ and $\alpha \rightarrow 0.$ Further, from the definition of $I(\xx)$ in \eqref{eqn:I_star_limit}, we have  
    $1/I(\xx) = c^\prime\inf\{ (\zz^\intercal \Sigma^{-1} \zz)^{\gamma/2}: \cup_{k \in [K]} \{\xx^\intercal B_k \zz > u_k\}  \} = c^\prime\min_{k \in [K]} \inf \{\zz^\intercal \Sigma^{-1} \zz: \xx^\intercal B_k \zz > u_k \}^{\gamma/2}.$ Since the constraints $\xx^\intercal B_k \zz$ are linear in the variable $\zz,$ a typical application of Lagrange duality leads to $1/I(\xx) = c^\prime \min_{k \in [K]} (u_k^2/\xx^\intercal B_k \Sigma B_k^\intercal  \xx)^{\gamma/2}.$ Then the resulting $\Dapprox$ in Theorem \ref{thm:solution_convergence} is given by, 
    \begin{align}
        \min_{\xx \in \mathcal{X}} c(\xx) \quad \text{s.t.} \quad  \xx^\intercal B_k \Sigma B_k^\intercal \xx \leq c^\prime u_k^2 \quad \forall k \in [K].   
        \label{eq:ccp-apx-eg}
    \end{align}
    Therefore the characterization in Theorem \ref{thm:solution_convergence} translates to  
    \begin{align*}
        v_\alpha^\ast \sim \frac{v^\ast}{\sigma_{\max}}\left(\frac{c^\prime}{\ln 1/\alpha}\right)^{1/\gamma} \quad \text{ and } \quad \xx_{\alpha}^\ast \sim \frac{\xx^\ast}{\sigma_{\max}} \left(\frac{c^\prime}{\ln 1/\alpha}\right)^{1/\gamma},
    \end{align*}
    where  $v^\ast$ and $\xx^\ast$ denote the optimal value and solution of \eqref{eq:ccp-apx-eg} and the target reliability level $1-\alpha \rightarrow 1.$ If the optimal solution set $\mathcal{X}^\ast$ of \eqref{eq:ccp-apx-eg} is not a singleton, then $d(s_\alpha \xx_\alpha^\ast, \mathcal{X}^\ast) \rightarrow 0.$ \hfill$\Box$
\end{example}


\subsubsection{A discussion on the scaling rate.}
First, note that Theorem \ref{thm:solution_convergence} precisely characterizes the rate at which an optimal solution $\xx_\alpha^\ast$ and its respective cost $v_\alpha^\ast = c(\xx_\alpha^\ast)$  vary with respect to the target reliability level $1-\alpha.$ Interestingly, this scaling rate $\xx_\alpha^\ast = v_\alpha^\ast = O(s_\alpha^r)$ is determinable entirely from (i) the constant $r$ in Assumptions \ref{assume:hom-safe-set} or \ref{assume:non-hom-safeset} capturing a certain rate of growth of  the constraint functions $\{g_k: k \in [K]\}$, and (ii) the function $\bar{F}(\cdot)$ which captures the rate at which the complementary CDF of the marginal distributions of $\xxi$ decay to zero. %Note that $r$ can be either positive or negative; see Example \ref{eg:portfolio_opt} for an instance where $r$ is negative. 
In the cases where $r > 0,$ as in Examples \ref{eg:transportation}-\ref{eg:nw-design}, greater reliability is attained by increasing the capacities of supplies (optimal $\xx_\alpha^\ast \rightarrow \infty$ ). On the other hand, in the case where  $r < 0$ as in the portfolio optimization setting, greater reliability is attained by decreasing the weights of the risky assets (optimal $\xx_\alpha^\ast \rightarrow \mv{0}$ ). Further, the dependence on $s_\alpha = \bar{F}^{-1}(\alpha)$ highlights that as the tails of the marginal distribution of $\xxi$
become heavier, the corresponding value of $s_\alpha$ increases. A more precise characterization of the growth rate of $s_\alpha$ under Assumptions $(\mathscr L)$ and $(\mathscr H)$ stipulating light-tailed and heavy-tailed distributions, respectively, are given in Lemma \ref{lem:salpha-growth-rate} below. 
\begin{lemma}
    \label{lem:salpha-growth-rate}
    As $\alpha \rightarrow 0,$ we have
    \begin{itemize}
        \item[(i)] $\log s_\alpha \sim \frac{1}{\gamma} \log\log \frac{1}{\alpha}$ under Assumption $(\mathscr L);$ and 
        \item[(ii)] $\log s_\alpha \sim    \frac{1}{\gamma} \log \frac{1}{\alpha}$ under Assumption $(\mathscr H).$ 
    \end{itemize}
\end{lemma}

