\subsection{Distortion of scaling under Wasserstein DRO} Suppose that the  ambiguity set in $\DROCCPalpha$ is given by 
\begin{equation}\label{eqn:Wasserstein_const}
    \mathcal P = \left\{\mathbb Q: d_W(\mathbb P,\mathbb Q)  \leq \eta\right\}, \text{ where } d_W(\mathbb P_1,\mathbb \Prob_2)=\inf_{\Pi(\Prob_1, \Prob_2)} \left[E_{\Pi}|\XX-\YY|^p \right]^{1/p}
\end{equation}
 is the Wasserstein distance of order $p \in [1,\infty)$ between any two probability measures $\mathbb P_1,\mathbb P_2$ supported on $\R^d$ and $\Pi(\Prob_1, \Prob_2)$ is the collection  of all joint distributions with marginals $\XX \sim \mathbb \Prob_1$ and $\YY \sim \mathbb \Prob_2$. Let $\xx_{\alpha}^{\tt W}$ be an optimal solution of the resulting distributionally robust formulation.
\begin{theorem}[\textbf{Conservativeness of Wasserstein DRO}]\label{lem:Wasserstein_CCP}
 Suppose that the constraint functions satisfy either Assumption \ref{assume:hom-safe-set} \underline{or} \ref{assume:non-hom-safeset} and Assumption \ref{assume:cost} holds. Let the  ambiguity set $\mathcal{P}$ in $\DROCCPalpha$  be the Wasserstein ball in \eqref{eqn:Wasserstein_const} for some $\eta \in (0,\infty)$ and  distribution $\Prob$  satisfying either (i) Assumption ($\mathscr{L}$) holds, or (ii) Assumption ($\mathscr{H}$) holds with $p < \gamma.$ Then for any $\varepsilon > 0,$ the cost of the optimal decision prescribed by $\DROCCPalpha,$ denoted by $c(\xx_{\alpha}^{\tt W}),$ satisfies
 \begin{align*}
    c(\xx_{\alpha}^{\tt W}) \geq v\alpha^{-(r/p+\varepsilon)},
 \end{align*}
 for all $\alpha$ sufficiently small and some positive constant $v$ that does not depend on $\alpha.$
% depending on $\eta,\varepsilon,$ and the problem instance. 
 As a result, $\varliminf_{\alpha \rightarrow 0} \frac{\log c(\xx_{\alpha}^{\tt W})}{\log v_{\alpha}^\ast} = \infty$ when $\Prob$ satisfies Assumption $(\mathscr L)$ and
 $\varliminf_{\alpha \rightarrow 0} \frac{\log c(\xx_{\alpha}^{\tt W})}{\log v_{\alpha}^\ast} \geq \gamma/p$ when $\Prob$ satisfies Assumption $(\mathscr H).$ 
 %$\liminf_{\alpha\to 0}[v_{\alpha}^{\tt W}]^{1/r} \alpha^{-1/\rho} = \infty$ as $\alpha\to 0$.
\end{theorem}

