\subsection{Inner approximations based on Bonferroni inequality}
\label{sec:bfi-approx}
As joint constraints are computationally more challenging than individual chance constraints, Bonferroni inequality has served as an intuitive and popular approach towards breaking up multiple constraints, such as in \eqref{eqn:CCP}, into individual probability constraints as below: For any positive constants $\eta_1,\ldots,\eta_d$ satisfying $\sum_{i=1}^d \eta_i = 1,$  consider
\begin{align}
   \qquad \inf_{\xx \in \mathcal{X}}\,c(\xx)  \quad \text{ s. t. } \quad \Prob\left\{ g_k(\xx,\xxi) \leq 0 \right\} \geq 1-\eta_k \alpha, \quad \forall k \in [K]. 
     \label{eqn:bfi-approx}
\end{align}
Indeed, for any $\xx$ satisfying the $K$ individual probability constraints in \eqref{eqn:bfi-approx}, we have $\Prob(\cup_{k \in [K]}\{ g_k(\xx,\xxi) > 0\}) \leq \sum_{k=1}^K \Prob(g_k(\xx,\xxi) > 0) \leq \sum_{k=1}^K \eta_k \alpha = \alpha,$ due to the Bonferroni's inequality. Consequently, any solution to \eqref{eqn:bfi-approx} in turn satisfies the probability  constraint in $\CCPalpha.$ %and hence can be considered to be prescribing ``safe" decisions. %The equally weighted case where $\eta_k =1/K$ is one common  


\begin{theorem}[\textbf{Scaling for Bonferroni inequality based approximation}]
\label{thm:bfi-approx}
%\em 
    Suppose Assumption~\ref{assume:cost}, Assumption~\ref{assume:constraint-functions-cvar},  and either Assumption ($\mathscr{L}$) or ($\mathscr{H}$) hold. 
    Let $v_\alpha^{\tt apx}$ and $\xx_\alpha^{\tt apx}$ denote, respectively, the optimal value and an optimal solution to the Bonferroni inequality based approximation in \eqref{eqn:bfi-approx}. Then the following hold as $\alpha \rightarrow 0$:
\begin{itemize}
    \item[a)] Under Assumption $(\mathscr{L}),$ the optimal value $v_\alpha^{\tt apx}$ and any optimal solution $\xx_\alpha^{\tt apx}$ satisfy
     $v_\alpha^{\tt apx} \sim {v}^\ast s_\alpha^{r}$ and $d(s_\alpha^{-r}\xx_{\alpha}^{\tt apx}, {\mathcal{X}}^\ast) \rightarrow 0,$ where ${v}^\ast$ and $\mathcal{X}^\ast$ are the optimal value and optimal solutions of the deterministic optimization problem $\Dapprox$ in \eqref{eq:d-approx};

    \item[b)] Under Assumption $(\mathscr{H}),$ the optimal value $v_\alpha^{\tt apx}$ and any optimal solution $\xx_\alpha^{\tt apx}$ satisfy
     $v_\alpha^{\tt apx} \sim \tilde{v} s_\alpha^{r}$ and $d(s_\alpha^{-r}\xx_{\alpha}^{\tt apx}, \tilde{\mathcal{X}}) \rightarrow 0,$ where $\tilde{v}$ and $\tilde{X}$ are the optimal value and optimal solutions of 
    \begin{align}
        \min_{\xx \in \mathcal{X}} \ c(\xx) \quad \text{ s.t. } \quad I_k(\xx) \leq \eta_k \quad \forall k \in [K], 
        \label{eqn:bfi-dapprox}
    \end{align}   
    with $I_k(\xx) = \int_{g_k^\ast(\xx,\zz) \geq 0} \varphi^\ast(\zz) d\zz.$
    \end{itemize}   
\end{theorem}

Theorem \ref{thm:bfi-approx} reveals that the inner approximation based on Bonferroni inequality features the same scaling as $\CCPalpha$. Hence the extent of conservativeness introduced by the formulation \eqref{eqn:bfi-approx}
remains bounded even as the problem becomes more challenging with the  target  level $1-\alpha$ approaching 1. Similar to CVaR approximation, the conservativeness of \eqref{eqn:bfi-approx} vanishes if the distribution of $\xxi$ is light-tailed and the resulting solution $\xx_{\alpha}^{\tt apx}$ coincides with a target solution $\xx_\alpha^\ast$ of the $\CCPalpha$  formulation  asymptotically. 
However, in the case of heavy-tailed distributions,  the limiting deterministic optimization problem in \eqref{eqn:bfi-dapprox} does not  match with \eqref{eq:d-approx}. In particular, note that the  constraint sets $\cap_{k \in [K]} \{\zz: \int_{g_k^\ast \geq 0} \varphi^\ast(\zz) d\zz \leq \eta_k \}$ and $\{\zz:\int_{g^\ast  \geq 0} \varphi^\ast(\zz) d\zz \leq 1\}$ are of very different nature even when we set $\eta_1 = \cdots = \eta_K.$ Hence one cannot expect the solution $\xx_{\alpha}^{\tt apx}$ to be proximal to the scaled solution set $cs_\alpha^r \mathcal{X}^\ast,$ which was a nice feature of CVaR-based inner approximations that cannot be guaranteed with Bonferroni inequality based inner approximations. 



\subsection{A line-search procedure to obtain  asymptotically optimal solutions for $\CCPalpha$}
\label{sec:line-search}
Consider a target reliability level $1-\alpha \in (0,1)$ and a solution $\xx^{\tt apx}_\alpha$ obtained by solving either the CVaR-based inner approximation in \eqref{eqn:cvar-approx} or the Bonferroni inequality based inner approximation in \eqref{eqn:bfi-approx}. Assuming the ability to evaluate the probability of constraint violation $p(\xx) = P(\max_{k \in [K]} \, g_k(\xx,\xxi) > 0)$ at any $\xx \in \mathcal{X},$ Algorithm  \ref{algo:Vanish_Regret} below outlines an  elementary  line search procedure which returns a strictly improved feasible solution to $\CCPalpha.$ This strict improvement is  guaranteed by the  observations in Lemma \ref{lem:line-search-properties} below.
\begin{lemma}
    \label{lem:line-search-properties}
    Suppose $\mathcal{X}$ is a cone and $p(\xx)$ is  continuous.  %on $\mathcal{X}.$ 
    Then under the assumptions of Thm. \ref{thm:convex_rel}, 
    \begin{itemize}
        \item[a)] the cost of the decisions parameterized by $\xx(t) = t^r\xx_\alpha^{\tt apx}$ is strictly increasing in $t > 0;$ 
        \item[b)] the decision  $\xx(t)$ is feasible for $\CCPalpha$ for any $t \geq t_\alpha,$ where $t_\alpha = \inf\{t \in [0,1]: p(t^r\xx_\alpha^{\tt apx}) \leq \alpha\};$
        \item[c)] we have $t_\alpha < 1$ and consequently $c(\xx^\prime_\alpha) <  c(\xx^{\tt apx})$ for the assignment $\xx^\prime_\alpha = t_\alpha^r \xx^{\tt apx}_\alpha.$
    \end{itemize}
\end{lemma}

\begin{algorithm}[h!] 
  \caption{Line search for improving an inner approximation's solution to be asymptotically optimal for $\CCPalpha$}
  % \DontPrintSemicolon
  \ \vspace{-2pt}\\
  \KwIn{Target reliability level $1-\alpha$} 
     \noindent \textbf{1. Solve an inner approximation to $\CCPalpha$}:  If $\xxi$ satisfies Assumption $(\mathscr L),$ obtain $\xx_\alpha^{\tt apx}$ by either solving \eqref{eqn:cvar-approx} or \eqref{eqn:bfi-approx}.
     If $\xxi$ satisfies Assumption $(\mathscr H),$ obtain $\xx_\alpha^{\tt apx}$ by solving \eqref{eqn:cvar-approx}.\\

  \noindent \textbf{2. Find the best feasible solution along the ray:}  Solve the one-dimensional line search  $t_\alpha = \inf\{t \in [0,1]: p(t^r\xx_\alpha^{\tt apx}) \leq \alpha\}.$ 


\noindent \textbf{3. Return} 
 $\xx_\alpha^\prime = t_\alpha^r \xx_\alpha^{\tt apx}$ as our candidate solution for solving $\CCPalpha.$ 
  \label{algo:Vanish_Regret}  
\end{algorithm}

Despite the simplicity of the line-search in Algorithm \ref{algo:Vanish_Regret},  Proposition \ref{prop:Approx_alg_guarantees} below demonstrates that the improved solution $\xx_\alpha^\prime$ returned by Algorithm \ref{algo:Vanish_Regret} is asymptotically optimal for $\CCPalpha$.
%; see Proposition \ref{prop:Approx_alg_guarantees} below. %Empirically,   Numerical Illustration \ref{num-eg:cvar-line-search} shortly following Proposition \ref{prop:Approx_alg_guarantees} demonstrates that the reduction in costs with this simple line search can  be as much as  4\% to 14\% in light-tailed instances and an impressive 50\% - 120\% in heavy-tailed instances. 
In Proposition \ref{prop:Approx_alg_guarantees} below,  recall that $v_\alpha^\ast$ denotes the optimal value of $\CCPalpha$ in \eqref{eqn:CCP}. 
\begin{proposition}
\label{prop:Approx_alg_guarantees}
Suppose the Assumptions in Theorem \ref{thm:convex_rel} and Lemma \ref{lem:line-search-properties} hold. Then the solution $\xx_\alpha^\prime = t_\alpha^r\xx_\alpha^{\tt apx}$ returned by Algorithm \ref{algo:Vanish_Regret} has vanishing relative optimality gap: Specifically, 
\begin{align*}
   \lim_{1-\alpha \rightarrow 1} \  \frac{c(\xx_\alpha^\prime) - v_\alpha^\ast}{v_\alpha^\ast} = 0, 
   \end{align*}
and Algorithm \ref{algo:Vanish_Regret} decreases the cost by the factor $\lim_{1-\alpha \rightarrow 1} c(\xx_\alpha^\prime)/c(\xx_\alpha^{\tt apx}) =  c.$
\end{proposition}

