\subsection{Proofs from Section~\ref{sec:Modelling Assumptions}} 

\noindent \textbf{Proof of Lemmas~\ref{lem:marginals-light}
and \ref{lem:marginals-heavy}: }First suppose that Assumption~($\mathscr{L}$) holds. Then, from Proposition~\ref{prop:ldp}, the sequence of random vectors $\{\xxi/\lambda^{\leftarrow}(n) :n\geq 0\}\in {\tt LDP}(\varphi^*)$. With $n=\lambda(t)$, note that then for each $i$, 
\begin{align*}
    \log \mathbb P(\xi_i \geq tz) &\sim -\lambda(t) \inf_{z_i \geq z}\varphi^*(\zz)\\
    &=-\lambda(t) \inf_{p_i>1} \varphi^*(\pp/z) = -\lambda(t) z^{-\gamma} \inf_{p_i>1}\varphi^*(\pp)
\end{align*}
The first statement above follows directly from the large deviations principle, and the second from Lemma~\ref{lem:RVs}. Setting the infimum above as $c_i$ completes the proof. Now, we have that 
\[
\bar F_i(tz)  =\exp\left\{-c_i z^{-\gamma} \lambda(t) [1+o(1)]\right\}
\]
and taking the maximum over all $i$,
\[
\bar F(tz) =\exp\left\{-\min_{i\in[d]} c_i z^{-\gamma} \lambda(t) [1+o(1)]\right\}
\]
Setting $\lambda(t) = -\log \bar F(t)$ above,  it follows that the multiplying constant $\min_i c_i =1$. Next suppose that Assumption~($\mathscr{H}$) holds. Then from Proposition~\ref{thm:HTT_RV}, note that 
\begin{align*}
    \mathbb P(\xi_i \geq tz) &\sim \bar F(t) \int_{z_1\geq z}\varphi^*(\zz)d\zz \\
    & = \bar F(t) z^{-\gamma}\int_{z_1\geq 1}\varphi^*(\zz)d\zz \quad 
\end{align*}
The second equality above follows upon changing variables from $z_1$ to $\zz/z$ and then using Lemma~\ref{lem:RVs}.
Setting $\nu(A_1)$ above as $c_i$ gives the first part of the proof. Taking the maximum over all $i$,
\[
\bar F(tz) = \max_{i\in[d]} c_i z^{-\gamma} \lambda(t) [1+o(1)]
\]
Setting $\lambda(t) = \bar F(t)$ above,  it follows that the multiplying constant $\max_i c_i =1$.
\qed
\subsection{Proofs from Section~\ref{sec:Asymptotics}} 
We introduce some simplifying notation which we will carry forward through the rest of the proofs.
Denote the function 
$g_t(\xx,\zz) = \max_{i} t^{-k} g_i(t^r\xx,t\zz)$.
Let 
\begin{equation}\label{eqn:level_sets_of_functions}
    \mathcal S_{t,\alpha,M}(\xx) = \{\zz: g_t(\xx,\zz) \leq \alpha\} \cap B_M \quad \text{and} \quad \mathcal S^*_{\alpha,M}(\xx) = \{\zz: g^*(\xx,\zz) \leq \alpha \}\cap B_M. 
\end{equation}
denote the $\alpha-$level set of $g_t(\xx,\cdot)$, and $g^*(\xx,\cdot)$ restricted to the $M-$norm ball. If $M=\infty$, we simply write $\mathcal S_{t,\alpha}$ and $\mathcal S^*_{t,\alpha}$ respectively. In what follows, let $\Upsilon(\xx) = \mathcal [S(\xx)]^{c}$ denote the set of realisations when the chance constraint is violated. Observe now, that \eqref{eqn:CCP} can be equivalently re-stated as
\begin{equation}\label{eqn:CCP_unsafe}
\min c(\xx) \quad \text{ s.t }\quad \mathbb P[\xxi\in \Upsilon(\xx) ] \leq \alpha.
\end{equation}

Defining $\Upsilon_t(\xx) := t^{-1}\Upsilon(t^r \xx)$, further note that
\begin{align*}
    \Upsilon_t(\xx) &= \left\{\zz/t: \max_i g_i(t^r\xx,\zz) > 0\right\} \\ 
    & = \left\{\zz: g_t(\xx,\zz) > 0\right\} \text{ replacing $\zz/t $ by $ \zz$ and multiplying by $t^{-\rho}$}\\
    & = \mathcal S_{t,0}^c(\xx) .
\end{align*}

The following technical lemmas are required to proceed with the subsequent proofs:
\begin{lemma}\label{lem:level_sets_containment}
    Suppose that Assumption~\ref{assume:hom-safe-set} or \ref{assume:non-hom-safeset} holds and that $\xx_t\to\xx \neq \mv 0$. Then, for every $(\varepsilon, M)>0$, there exists an $t_0$ such that for all $t>t_0$, 
\begin{equation}\label{eqn:level_sets_containment}
        \mathcal S_{t, 0,M}(\xx_t) \subseteq [\mathcal S^*_{0, M}(\xx)]^{1+\varepsilon} \quad \text{ and }\quad  \mathcal S_{-\varepsilon, M}^*(\xx) \subseteq \mathcal S_{t,0,M}(\xx_t)  
    \end{equation}
\end{lemma}
\begin{lemma}\label{lem:compact_containment}
    There exists $\alpha_0>0$  and a compact set $K$ such that for all $\alpha<\alpha_0$, $\mathcal Y^*_\alpha \subset K$.
\end{lemma}
Let 
\[
I(\xx) = \begin{cases}
    \inf{\varphi^*(\xx) : g^*(\xx,\zz) \geq 0}\}]^{-1}\ [\min_i c_i] \quad\quad \quad \text{ if Assumption~($\mathscr{L}$) holds}\\
    \int_{g^*(\xx,\zz)\geq 0}\varphi^*(\zz)d\zz\ [\max_i c_i]^{-1} \quad\quad \quad\quad\quad\quad \text{ if Assumption~($\mathscr{H}$) holds}
\end{cases}
\]
\begin{lemma}\label{lem:extended_functional}
    Define the extended functionals:
\begin{equation}\label{eqn:Ext_functional}
    \bar{c}_t(\xx) = c(\xx) + \chi_{\Lev_1(I_t)}(\xx) \quad \text{ and }\quad c^*(\xx) = c(\xx) + \chi_{\Lev_1(I^*)}(\xx)
\end{equation}
Then, $\bar c_t\to c^* $ epigraphically.
\end{lemma}

\noindent \textbf{Proof of Proposition~\ref{prop:prob-convergence_LT}:} 
Denote the function 
\[
G_t(\xx) = \frac{\log\mathbb P \left(g_t(\xx, \xxi_t) > 0\right) }{\lambda(t)}
\]
Note that proving the uniform convergence in Proposition~\ref{prop:prob-convergence_LT} is then equivalent to proving the continuous convergence of $G_t \to -G_0$ (see \cite{rockafellar2009variational}, Theorem 7.14). To this end, rewrite using the notation defined previously 
\begin{equation}\label{eqn:I_t}
    G_t(\xx) = \frac{\log \mathbb P\left( \xxi_t \in \Upsilon_t(\xx) \right)}{\lambda(t)}.
\end{equation}

% \begin{lemma}\label{lem:level_sets_containment}
%     Suppose that Assumption~\ref{assume:non-hom-safeset} holds and that $\xx_t\to\xx \neq \mv 0$. Then, for every $(\varepsilon, M)>0$, there exists an $t_0$ such that for all $t>t_0$, 
% \begin{equation}\label{eqn:level_sets_containment}
%         \mathcal S_{t, 0,M}(\xx_t) \subseteq [\mathcal S^*_{0, M}(\xx)]^{1+\varepsilon} \quad \text{ and }\quad  \mathcal S_{-\varepsilon, M}^*(\xx) \subseteq \mathcal S_{t,0,M}(\xx_t)  
%     \end{equation}
% \end{lemma}
 \noindent \textbf{Step 1) Upper Bound: } Recall that $\Upsilon_t(\xx_t) = \mathcal S_{t,0}^c(\xx_t)$ and note the following sequence of set operations:
 \begin{align*}
      \mathcal S_{t,0}^c(\xx_t) &=   (\mathcal S_{t,0}^c(\xx_t) \cap B_{2M})  \cup (\mathcal S_{t,0}^c(\xx_t) \cap B_{2M}^c) \\
      & \subseteq ([(\mathcal S_{t,0}(\xx_t) \cap B_M) \cup (\mathcal S_{t,0}(\xx_t) \cap B_M^c)]^c \cap B_{2M})\cup B_{2M}^c \\
      &\subseteq (\mathcal S_{t,0,M}^c(\xx_t) \cap B_{2M}) \cup B_{2M}^c \quad \,\text{ dropping the union above}.
 \end{align*}
 Then, observe that
 \begin{equation}\label{eqn:contain_upper}
\mathbb P\left(\xxi_{t} \in \Upsilon_{t}(\xx_t) \right) \leq \mathbb P(\xxi_{t} \in [\mathcal S_{0,t,M}(\xx)]^c \cap B_{2M}) + \mathbb P(\xxi_{t} \in  B_{2M}^c).
 \end{equation}
The second containment in \eqref{eqn:level_sets_containment} implies that for a fixed $\delta>0$,
\[
    \mathbb P(\xxi_{t} \in [\mathcal S_{0,t,M}(\xx)]^c \cap B_{2M}) \leq \mathbb P(\xxi_{t} \in  [\mathcal S^*_{-\delta,M}(\xx)]^{c} \cap B_{2M})  \text{ for all large enough $t$}. 
\]
Consequently, for all large enough $t$, one has that 
\[
G_t(\xx_t ) \leq \frac{\log \left\{\mathbb P(\xxi_{t} \in \mathcal [\mathcal S^*_{-\delta,M}(\xx)]^{c} \cap B_{2M}) +  \mathbb P(\xxi_{t} \in  B_{2M}^c)\right\}}{\lambda(t)}.
\]
Recall that from Proposition~\ref{prop:ldp}, the sequence $\xxi_{t}\in {\tt LDP}(\varphi^*)$. Upon applying the LDP upper bound from \eqref{eqn:LDP}, 
\begin{equation*}
\limsup_{t\to\infty} G_t(\xx_t)\leq - \min\left\{  \inf_{\zz\in [\mathcal{S}^*_{-\delta,M}(\xx)]^c \cap B_{2M}} \varphi^*(\zz), \inf_{\zz \in B_{2M}^c} \varphi^*(\zz)\right\}. 
\end{equation*}
Note that as $\delta\to 0$, the sets $[\mathcal S_{-\delta,M}^*(\xx)]^{c}\cap B_{2M}$ decrease to $[\mathcal S_{0,M}^*(\xx)]^{c}\cap B_{2M}$ and are relatively compact in the sense that the closure of
\[
\bigcup_{\delta>0} [\mathcal S_{-\delta,M}^*(\xx)]^{c}\cap B_{2M} \text{ is compact} 
\]

Following \cite{Langen} Theorem 2.2, for a fixed $\varepsilon>0$, whenever  $\delta<\delta_0$, $\inf_{\zz\in [\mathcal S_{-\delta,M}^*(\xx)]^{c}\cap B_{2M}} \varphi^*(\zz) \geq \inf_{\zz\in [\mathcal S_{0,M}^*(\xx)]^{c}\cap B_{2M}} \varphi^*(\zz) -\varepsilon$. Next, observe that $\mathcal [S_{0,M}^*(\xx)]^c\cap B_{2M} = [\Upsilon^*(\xx) \cup B_{M}^c] \cap B_{2M}  $. Consequently,
\[
 \inf_{\zz\in [\mathcal S_{0,M}^*(\xx)]^{c}\cap B_{2M}} \varphi^*(\zz)  = \min\left\{\inf_{\zz\in  \Upsilon^*(\xx) \cap B_{2M} } \phi^*(\zz), \inf_{\|\zz\|\in [M,2M]} \varphi^*(\zz) \right\}
\]
For the above choice of $\delta$, 
\begin{equation}\label{eqn:LDP_upper}
\limsup_{t\to\infty} G_t(\xx_t) \leq -\min\left\{  \inf_{\zz\in \Upsilon^*(\xx)} \varphi^*(\zz) -\varepsilon, \inf_{\zz \in B_{M}^c} \varphi^*(\zz)\right\}. 
\end{equation}
where we can replace $\Upsilon^*(\xx) \cap B_{2M}$ by $\Upsilon^*(\xx)$ in the infimum since $\Upsilon^*(\xx) \cap B_{2M} \subset \Upsilon^*(\xx)$.  

Note that from Lemma~\ref{lem:RVs}, $\varphi^*$ is a $\gamma$-homogeneous function. Therefore, by selecting $M$ sufficiently large, the second infimum above can be made as large as desired. 
Whenever the non-vacuousness condition holds,
 note that $\Upsilon^*(\xx)\neq \emptyset$. Then, since $\varphi^*$ is $\gamma-$homogeneous, for all $\xx$, $G_0(\xx) = \inf\{\varphi^*(\zz):\zz\in\Upsilon^*(\xx)\}< \infty $.
Further, 
Hence, there exists an $t_0$ such that for all $t>t_0$, 
\begin{equation}\label{eqn:lower_I}
    G_t(\xx_t)  \leq  - G_0(\xx) +\varepsilon.
\end{equation}


\noindent \textbf{ii) Lower Bound: }We now prove a lower bound to match \eqref{eqn:lower_I}. For any $(\delta,M)>0$,
\begin{align*}
    \mathbb P(\xxi_{t} \in \Upsilon_{t}(\xx_t)) &\geq  \mathbb P(\xxi_{t} \in \Upsilon_{t}(\xx_t)\cap B_{M})\\
    &= \mathbb P(\xxi_{t} \in \mathcal [S_{t,0,M}(\xx_t)]^c\cap B_{M}) 
\end{align*}
To see the last part, note that 
\[
\mathcal  S_{t,0,M}^c(\xx_t) \cap B_M= [\mathcal S_{t,0}(\xx_t)\cap B_M]^{c} \cap B_M = [\mathcal S_{t,0}^c(\xx_t)\cup B_M^c]\cap B_M = \mathcal S_{t,0}^c(\xx_t)\cap B_M
\]
Utilizing the first containment in \eqref{eqn:level_sets_containment}, 
\begin{align}\label{eqn:lb}
    \mathbb P(\xxi_{t} \in \Upsilon_{t}(\xx_t)) &\geq \mathbb P(\xxi_{t} \in ([\mathcal S_{0,M}^*(\xx)]^{1+\delta})^c \cap B_{M}), 
\end{align}
where the statement above is for all $t>t_0$, chosen in accordance with Lemma~\ref{lem:level_sets_containment}.
Invoke the large deviations lower bound to get that 
\[
\liminf_{n\to\infty} \frac{\log \mathbb P(\xxi_{t} \in ([\mathcal S_{0,M}^*(\xx)]^{1+\delta})^c \cap B_{M})}{\lambda(t)}  \geq -\inf_{\zz\in [\mathcal S_{0,M}^*(\xx)]^{1+\delta})^c \cap B_{M}}\varphi^*(\zz).
\]
To conclude notice the convergence $([\mathcal S_{0,M}^*(\xx)]^{1+\delta})^c \cap B_{M} \nearrow \Upsilon^*(\xx) \cap B_M$ as $\delta\downarrow 0$, and that the right hand side in this convergence is relatively compact.
Therefore, upon an application of \cite{Langen}, Theorem 2.2(ii), for a small enough $\delta$,
\[
\inf_{\zz\in [([\mathcal S_{0,M}^*(\xx)]^{1+\delta})^c \cap B_{M}]}\varphi^*(\zz) \leq \inf_{\zz\in \Upsilon^*(\xx) \cap B_{M}}\varphi^*(\zz) +\varepsilon.
\]
Plugging the above display into the large deviations lower bound: 
\[
\liminf_{t\to\infty} G_t(\xx_t) \geq -\inf_{\zz\in \Upsilon^*(\xx) \cap B_{M}}\varphi^*(\zz) -\varepsilon = -G_0(\xx)-\varepsilon.
\]
Since $M$ and $\varepsilon$ are arbitrary, combining the above convergence with \eqref{eqn:lower_I} yields that  $G_t(\xx_t) \to -G_0(\xx)$, or $G_t$ converges continuously and therefore uniformly to $-G_0$.  \qed


\noindent \textbf{Proof of Proposition~\ref{prop:prob-convergence_HT}: }
Define 
\[
G_t(\xx) = \frac{\mathbb P(\xxi \in \Upsilon_t(\xx))}{\lambda(t)}
\]
Similar to the proof of Proposition~\ref{prop:prob-convergence_LT}, it is sufficient to 
show that $G_t\to G_0$. 

\noindent \textbf{i) Upper Bound:} Recall that from \eqref{eqn:contain_upper}, 
\[
\mathbb P\left(\xxi_{t} \in \Upsilon_{t}(\xx_t) \right) \leq \mathbb P(\xxi_{t} \in  [\mathcal S^*_{-\delta,M}(\xx)]^{c} \cap B_{2M})  + \mathbb P(\xxi_t\in B_{2M}^c)\text{ for all large enough $t$} 
\]
Observe that the non-vacuousness of the set-valued map $\mathcal S^*$ implies that $\mv 0 \not \in \mathcal S^*_{0,M}(\xx)$. Note now that for all small enough $\delta$, $\mv 0 \not \in [\mathcal S_{-\delta, M}(\xx)]^{c}$. Using Proposition~\ref{thm:HTT_RV},
\[
[\lambda(t)]^{-1} \mathbb P(\xxi_{t} \in  [\mathcal S^*_{-\delta,M}(\xx)]^{c} \cap B_{2M}) \to \nu([\mathcal S^*_{-\delta,M}(\xx)]^{c} \cap B_{2M}) \text{ as  } t \to \infty
\]
Further note that $[\mathcal S^*_{-\delta,M}(\xx)]^{c}\cap B_{2M} \uparrow [\mathcal S^*_{0,M}(\xx)]^c\cap B_{2M}$. Then, one has that for all small enough $\delta$,
$\nu(\mathcal S^*_{-\delta,M}(\xx)) \leq \nu (\mathcal [S^*_{0,M}(\xx)]^{c} \cap B_{2M}) + \varepsilon$. 
This implies that
\[
\limsup_{t\to\infty} [\lambda(t)]^{-1}\mathbb P\left(\xxi_{t} \in \Upsilon_{t}(\xx_t) \right)\leq \nu([\mathcal S^*_{0,M}(\xx)]^c\cap B_M) + \nu(B_M^c) +\varepsilon
\]
Finally, since $(\varepsilon,M)$ are arbitrary $\limsup_{t\to\infty} [\lambda(t)]^{-1}\mathbb P\left(g(t^r\xxi,\xx_t)>0\right) \leq \nu(\Upsilon^*(\xx))$. 

\noindent \textbf{ii) Lower Bound: }For the matching lower bound, we start with \eqref{eqn:lb}: 
\[
P(\xxi_t\in \mathcal U_t(\xx_t)) \geq P(\xxi_t \in ([\mathcal S_{0,M}^*(\xx)]^{1+\delta})^{c} \cap B_M)
\]
Now, apply Proposition~\ref{thm:HTT_RV} to obtain that 
\[
\liminf_{t\to\infty } [\lambda(t)]^{-1} P(\xxi_t\in \mathcal U_t(\xx_t)) \geq \nu([\mathcal S_{0,M}^*(\xx)]^{1+\delta})^c \cap B_M)
\]
Since $(\delta,M)$ are arbitrary, the above display implies that $\liminf_{t\to\infty } [\lambda(t)]^{-1} P(\xxi_t\in \mathcal U_t(\xx_t)) \geq \nu(\Upsilon^*(\xx))$. Noting that $\nu(\Upsilon^*(\xx)) = \int_{g^*(\xx,\zz)\geq 0}\varphi^*(\zz)d\zz$ completes the proof.\qed


\noindent \textbf{Proof of Theorem~\ref{thm:solution_convergence}: } 
With $t = s_\alpha$ (we will suppress the dependence of $t$ on $\alpha$ to simplify notation), recall that from Lemmas~\ref{lem:marginals-light}-\ref{lem:marginals-heavy}, 
\[
\lambda(t) = \begin{cases}
- \log \alpha  [\min_i c_i](1+o(1)) \quad\quad  \text{ if Assumption~($\mathcal L$) holds and}\\
 \alpha(1+o(1)) / [\max_i c_i] \quad  \quad\quad\quad\text{ if Assumption~($\mathcal H$) holds }
\end{cases}
\]
 Now, note that the \eqref{eqn:CCP}
can be re-written as (using the homogeneity of $c(\cdot)$)
\[
t^r \min\{ c(\xx/t^r) : I_t(\xx/t^r) \leq 1\} \text{ where } I_t(\xx) =\begin{cases}
    [\min_i c_i+o(1)]/ \times G_t(\xx) \quad \text{ if Assumption~($\mathcal L$) holds and}\\
    G_t(\xx)/[\max_i c_i] \quad \ \ \ \ \text{ if Assumption~($\mathcal H$) holds}
\end{cases}
\]
Let $ y_\alpha^*$ and $\mathcal Y_\alpha^*$ be the optimal value and solutions of the optimization problem 
\[
O_\alpha: \min\{c(\pp) : I_t(\pp) \leq 1\}
\]
