\noindent \textbf{Proof of Proposition~\ref{prop:exp-div} and Table~\ref{tab:f-div-scalepreserving}: }
Observe that from Theorem~\ref{thm:f-div-DRO}, the scaling rate $t_\alpha$ governs the rate of increase of costs. To prove the strong (resp.) weak rate preserving property, it is therefore sufficient to prove that for all $\mathbb Q$ in $\mathcal P,$ $\limsup_{\alpha\to 0} t_\alpha/s_\alpha <\infty$ (resp. $\limsup_{\alpha\to 0} \log t_\alpha/\log s_\alpha \leq 1$), where $t_\alpha$ and $s_\alpha$ are as defined previously.
First, note that 
\begin{equation}\label{eqn:t_ratio}
    \frac{t_{\alpha}}{s_{\alpha}} = \frac{\bar F^{\leftarrow}(\alpha/g(\eta/\alpha)) }{\bar F^{\leftarrow}(\alpha)} \text{ and } \frac{\log t_{\alpha}}{\log s_{\alpha}}  = \frac{\log \bar F^{\leftarrow}(\alpha/g(\eta/\alpha))}{\log \bar F^{\leftarrow}(\alpha)}
\end{equation}

\noindent  \textbf{a)} Here, suppose that $f(x)/x =\Omega(x^p)$ for some $p>0$. Then, note that $g(x) = o(x^{1/p})$. When Assumption~($\mathscr{L}$) holds, recall that from Lemma~\ref{lem:salpha-growth-rate}, 
$\log \bar F^{\leftarrow}(t) \sim \gamma^{-1}\log \log(1/t)$ as $t\to 0$. Then,
\[
\bar F^{\leftarrow}(\alpha/g(\eta/\alpha)) = \exp(\gamma^{-1}\log \log (o((\eta/\alpha)^{1/p})/\alpha) ) = \exp(\gamma^{-1}\log \log (o((1/\alpha)^{1/p+1}))
\]
Substituting this into \eqref{eqn:t_ratio}, 
\begin{equation}\label{eqn:lt_lim}
    \varlimsup_{\alpha\to 0}\frac{t_\alpha}{s_\alpha} \leq 
\varlimsup_{\alpha\to 0} \frac{\exp(\gamma^{-1}\log \log ((1/\alpha)^{1/p+1})}{\exp(\gamma^{-1}\log \log (1/\alpha))} <\infty 
\end{equation}
Suppose now that Assumption~($\mathscr{L}$) holds.
Note that \eqref{eqn:lt_lim} also demonstrates when $f(x)/x \sim \exp(x)$, $t_\alpha = O(s_\alpha)$, since then $\bar F^{\leftarrow}(\alpha/g(\eta/\alpha)) = \exp(\gamma^{-1}\log \log (1/\alpha)^{1+o(1)})$.


\noindent \textbf{b)} Here, suppose $f(x)/x \sim \exp(x^p)$ for some $p$. This implies that $g(x) = o((\log x)^{1/p})$. If Assumption~($\mathscr{H}$) holds in addition, then note further that 
by Lemma~\ref{lem:salpha-growth-rate}, $\log \bar F^{\leftarrow}(t) \sim \gamma^{-1}\log (1/\alpha)$. 
Then,
\[
\log \bar F^{\leftarrow}(\alpha/g(\eta/\alpha))  = \gamma^{-1} \log(g(\eta/\alpha)/\alpha)(1+o(1)) = \gamma^{-1}\log(1/\alpha) (1+o(1)),
\]
where the last statement is because $g(x) = o((\log x)^{1/p})$. 
Substituting this into \eqref{eqn:t_ratio}, 
\[
\varlimsup_{\alpha\to 0}\frac{\log t_\alpha}{\log s_\alpha} = 
\varlimsup_{\alpha\to 0} \frac{\gamma^{-1}(1+o(1))\log(1/\alpha)}{\gamma^{-1}(1+o(1))\log(1/\alpha)} \leq 1 
\]
Suppose instead Assumption~$(\mathscr{L})$ holds. From Lemma~\ref{lem:salpha-growth-rate}, $\log \bar F^{\leftarrow}(t) \sim \gamma^{-1}\log \log (1/\alpha)$. 
\noindent \textbf{c) }Suppose that $u(x) :=f(x)/x \sim x^{p}$ for some $p>0$. Then, note that $g = u^{\leftarrow} \in \RV(1/p)$. If Assumption~($\mathscr{H}$) holds in addition, then note further that 
by Lemma~\ref{lem:salpha-growth-rate}, $\log \bar F^{\leftarrow}(t) \sim \gamma^{-1}\log (1/\alpha)$. Substituting this into \eqref{eqn:t_ratio}, 
\[
 \bar F^{\leftarrow}(\alpha/g(\eta/\alpha))) =   \exp(\gamma^{-1}\log(g(\eta/\alpha)/\alpha))(1+o(1)) ) = \exp((1/p+1)\gamma^{-1})\log(\eta/\alpha))(1+o(1)))
\]
Consequently, since $p>0$,
\[
\varliminf \frac{\log t_{\alpha}}{\log s_{\alpha}} = \frac{((1/p+1)\gamma^{-1})\log(1/\alpha)(1+o(1)))}{(\gamma^{-1} \log(1/\alpha)(1+o(1)))} >1  
\]





\noindent \textbf{d) }Next suppose that $u(x) \sim (\log x)^{p}$ for some $p>0$ and Assumption~($\mathscr{L}$) holds. Since $g = u^{\leftarrow
}$, one has that $g(x) = \exp(x^{1/p}(1+o(1)))$. From Lemma~\ref{lem:salpha-growth-rate} note that here 
$\log \bar F^{\leftarrow}(t) \sim \gamma^{-1}\log \log(1/t)$ as $t\to 0$. 
Substituting this into \eqref{eqn:t_ratio}, 
\begin{align*}
    \bar F^{\leftarrow}(\alpha/g(\eta/\alpha))& = \exp(\gamma^{-1}\log \log (\exp(\eta/\alpha)^{1/p}/\alpha) (1+o(1))) \\
    &= \exp((p\gamma)^{-1}\log(\eta/\alpha)(1+o(1))) \text{ for every }\mathbb Q\in \mathcal P
\end{align*}

Consequently, 
\[
\frac{t_{\alpha}}{s_{\alpha}}  = \frac{\exp((p\gamma)^{-1}(1+o(1))\log(\eta/\alpha))}{\exp(\gamma^{-1}(1+o(1))\log \log (1/\alpha))} \to \infty \text{ as }\alpha\to 0. 
\]
\qed

% Note that since $\mathcal S^*$ is a non-vacuous limiting set, there exists $\xx_0$ for which $\inf_{\mathcal \zz\in \mathcal E}\{\|\zz\|: \ \zz\in \Upsilon(\xx_0)\} >0$. Using the homogeneity of $\varphi^*$ furnished by Lemma~\ref{lem:Phi_homogeneous}, $I^*(\xx_0) = \inf_{\zz\in \mathcal E}\{\varphi^*(\zz): \ \zz\in \Upsilon^*(\xx_0)\}^{-1}<\infty$, and thus, $\mathcal Y^*$ is a contained in a compact set. 
\noindent \textbf{Proof of Theorem~\ref{lem:Wasserstein_CCP}: }
Note that for any $\mathbb Q_0 \in \mathcal P$, the cost of $\DROCCPalpha$ is at least as much as $v_\alpha^*(\mathbb Q)$.
In order to complete the proof, we hence demonstrate that so long as Assumption~($\mathscr{L}$) or ($\mathscr{H}$) is satisfied, there exists a measure $\mathbb Q_0$ which satisfies Assumption~($\mathscr{H}$) with $\gamma= p+\varepsilon$ for any $\varepsilon>0$. Consequently, one has that $c(\xx_{\alpha}^{\tt W}) \geq v \alpha^{r/p +\varepsilon}$. 

We use the following approach to show the existence of such as measure $\mathbb Q_0$: suppose there exists a coupling $\mv{\Pi}$ of $\xxi$ and $\xxi_0$ (where $\xxi_0$ has the distribution $\mathbb Q_0$) such that
$E_{\Pi}[\|\xxi-\xxi_0\|_p]\leq \eta$ and $v_\alpha^*(\mathbb Q_0)\geq v \alpha^{r/p +\varepsilon}$. . 
Then, 
\[
d_{W}(\mathbb P,\mathbb Q_0) \leq E_{\Pi}[\|\xxi-\xxi_0\|_p], \text{ from the definition of Wasserstein distance}.
\]
Then, $v_{\alpha}^{\tt DRO} \geq v \alpha^{r/p +\varepsilon}$. 

The rest of the proof is focused on demonstrating the existence of such a coupling, and is completed in two steps. Suppose the random variable $\xxi_0$ is defined as the following mixture:
\[
\xxi_0 = (1-B_\delta ) \xxi + B_\delta \mv{T},
\]
where $B_\delta$ is a Bernoulli random variable with $P(B_\delta =1) =\delta$ (to be chosen later), and $\mv{T}$ is a standard multivariate-t distribution with $(p+\varepsilon)$ degrees of freedom which are independent of $\xxi$ and each other. Note that the joint density $\xxi_0$ can be expressed as
\begin{equation}\label{eqn:xi0_density}
    \tilde f(\zz_1,\zz_2) = \delta f_{\xxi}(\zz_1) f_{\mv{T}}(\zz_2)  + (1-\delta)f_{\xxi}(\zz_1) \mv{1}(\zz_1=\zz_2)
\end{equation}
\textbf{i) Show that $\xxi_0$ satisfies Assumption~$\mathscr{H}$ with $\gamma =p+\varepsilon$: }Note first that by  construction, $\mv T$ satisfies Assumption~($\mathscr{H}$) with $\gamma =(p+\varepsilon)$. Now,
\begin{align*}
    \bar F_{0,i}(tz) &=  (1-\delta) \bar F_{i}(tz)+ \delta \bar F_{\mv T,i}(tz)\\
   & \sim \delta \bar F_{\mv T,i}(tz) \\
    &\sim \delta c_i z^{-\gamma}\bar F_{\mv T}(t) \text{ since $\mv T$ satisfies Assumption~($\mathscr{H}$)}
\end{align*}
Similarly, 
\begin{align*}
f_{0}(t\zz) &= (1-\delta)f_{\xxi}(t\zz) + \delta f_{\mv T}(t\zz)\\
& = (1-\delta) \exp(- \lambda(t) \varphi^*(\zz)(1+o(1))) +\delta  \bar F_{\mv T}(t)(1+o(1)) \varphi^*_0(\zz)\\
&\sim \delta  \bar F_{\mv T}(t)\varphi^*_0(\zz) 
\end{align*}
Combining the above two displays shows that $\xxi_0$ satisfies Assumption~($\mathscr{H}$) with $\gamma = (p+\varepsilon)$.

\noindent \textbf{ii) Bound Wasserstein distance: } 
Note that 
\begin{align*}
    E_{\Pi}[\|\xxi-\xxi_0\|_p] &= \int_{(\zz_1,\zz_2)} \|\zz_1-\zz_2\|^p \, d\Pi(\zz_1,\zz_2) = 
    \delta \int_{(\zz_1,\zz_2)}\|\zz_1-\zz_2\|^p f_{\xxi}(\zz_1)f_{\mv T}(\zz_2) d\zz_1d\zz_2\\
    &\leq \delta \left(\left(\int_{\zz_1} \|\zz_1\|^p f_{\xxi
    }(\zz_1)d\zz_1 \right)^{1/p}+  \left(\int_{\zz_2} \|\zz_2\|^p f_{\mv{T}}(\zz_2) d\zz_2\right)^{1/p}\right)^p
\end{align*}
To see the last statement, recall that from Minkowski's inequality, for two functions $\|f+g\|_p\leq \|f\|_p+\|g\|_p$. Setting $f(\zz_1,\zz_2) =\zz_1$ and $g(\zz_1,\zz_2) = -\zz_2$ to get the last inequality. To demonstrate that both the integrals above are finite, we perform the polar co-ordinate transformation: $\zz =r\pphi$, and note that $d\zz = r^{d-1}drd\pphi$. Substituting this above, 
\begin{equation}\label{eqn:integrals}
    \int_{\zz_1}\|\zz_1\|^p f_{\xxi}(\zz_1) d\zz_1 = \int_{(r,\pphi)} r^{d-1+p}f_{\xxi}(r\pphi)drd\pphi \text{ and } \int_{\zz_2}\|\zz_2\|^p f_{\mv{T}}(\zz_2) d\zz_2 = \int_{(r,\pphi)} r^{d-1+p}f_{\xxi}(r\pphi)drd\pphi
\end{equation}
To demonstrate the integrals are finite, we show that their tails integrate to $0$. To this end,
note that as $r\to\infty,$ $f_{\xxi}(r\pphi)  = \exp(-r^\gamma \varphi^*(\pphi)(1+o(1)))$, uniformly over $\pphi\in \mathcal E\cap \mathcal S^{d-1}$. Now,  
\[
\int_{r>m,\pphi} r^{d-1}f_{\xxi}(r\pphi) drd\pphi \leq (2\pi)^d \int_{r>m} r^{d-1}\exp(-0.5\varphi^*r^{\gamma})dr \to 0 \text{ as } r\to\infty 
\]
where $\varphi^*= \inf_{\pphi\in \mathcal E\cap \mathcal S^{d-1}} \varphi^*(\pphi)$. Therefore, the tail of the first expression in \eqref{eqn:integrals} goes to $0$.

For the second integral in \eqref{eqn:integrals}, note that from Assumption~($\mathscr{H}$), $f_{\mv T}(r\pphi) \sim r^{-(d+p+\varepsilon)}\varphi^*_0(\pphi)$. Then, similar to the previous case:
\begin{align*}
    \int_{r>m,\pphi} r^{d-1}f_{\mv{T}}(r\pphi)drd\pphi &\leq  \varphi^*_0 (2\pi)^d \int_{r>m} r^{d-1}r^{-(d+p+\varepsilon)} dr \to  0 \text{ as }r\to\infty.
\end{align*} 
where $\varphi^* = \sup_{\pphi\in \mathcal S^{d-1}}\varphi^*_0(\pphi)$.
Putting the above two displays together, the integrals in \eqref{eqn:integrals} are bounded, and upon choosing $\delta$ sufficiently small, it is possible to make $E_{\Pi}[\|\xxi-\xxi_0\|^p]\leq \eta$. \qed 


