\noindent\textbf{Proof of Theorem~\ref{lem:moment_ambiguity}: }We demonstrate that for each choice of dispersion measure in the theorem statement, there exists a distribution $\mathbb Q_0$ which satisfies the conditions of Assumption~($\mathscr{H}$) with $\gamma = p+\varepsilon$, where $\varepsilon>0$ can be taken to be arbitrary. Then $v_\alpha^{\tt DRO}$ is at least as much as the cost of $\CCPalpha$, where $\xxi\sim \mathbb Q_0$, where the latter quantity grows as $v^*\alpha^{-(r/(p+\varepsilon))}$ due to Theorem~\ref{thm:solution_convergence}.

\noindent \textbf{Case i) $d =d_{\tt cov}$: }Here, let $\mathbb Q_0$ be a multivariate $t$ distribution with $2+\varepsilon$ degrees of freedom, mean $\mv{\mu}$ and covariance matrix $\mv{\sigma}$. Clearly $\mathbb Q_0\in \mathcal P$, and from Example~\ref{eg:Elliptical_densities}, $\mathbb Q_0$ satisfies Assumption ($\mathscr{H}$) with $\gamma = p+\varepsilon$. Consequently, the theorem statement holds as a result of the discussion above.

\noindent \textbf{Case ii) $d =d_{\tt ad,p}$ (or) $d =d_{\tt sd,p}$: } Once again, take $\mathbb Q_0$ to be a multivariate $t$-distribution with $p+\varepsilon$ degrees of freedom, whose mean is $\mv{\mu} = (\mu_1,\ldots,\mu_d)$, and whose marginals have a scale of $\mv{\tau} = (\tau_1\ldots,\tau_d)$. Note that here, $E[|\xi_i-\mu_i|^p]<\infty$ and that this quantity decreases with $\tau_i$. Hence, when $\tau_i$ is such that for all $i$, $E[|\xi_i-\mu_i|^p]<\sigma_i$, $\mathbb Q_0\in \mathcal P$, and the conditions of the theorem hold.
For $d= d_{\tt sd,p}$, note that $E[|\xi_i-\mu_i|^p] > \max\{E[(\xi_i-\mu_i)_+^p], E[(\mu_i-\xi_i)_+^p]\}$, and repeat the same steps as before.

\noindent \textbf{Case iii) $d =d_{\tt norm,p}$: } Observe that
\[
E\left[\|\xxi-\mv{\mu}\|^p \leq d^p \left(E[|\xi_1 -\mu_1|^p] +\ldots+ E[|\xi_d -\mu_d|^p] \right)\right]
\]
We now choose $\mv{\tau}$ in part ii) above, so that each of $E\left[|\xi_i-{\mu}_i|^p\right] \leq d^{-(p+1)}\sigma$. Then, repeating the calculation of part ii), $E\left[\|\xxi-\mv{\mu}\|^p\right] \leq \eta$, and $\mathbb Q_0$ satisfies Assumption ($\mathscr{H}$) with $\gamma=p+\varepsilon$.\qed


