\noindent \textbf{Proof of Theorem~\ref{thm:convex_rel}: } 
Our proof strategy is identical to the one used in Theorem~\ref{thm:solution_convergence}. Consider the scaled optimization problem:
\begin{equation}\label{eqn:Oalpha}
    O_{\alpha}^{\tt rel}:  \min\{c(\xx): J_\alpha(\xx) \leq 0\},\text{ where }J_\alpha(\xx) = {\tt CVaR}_{1-\alpha}\left[\max_{k}\eta_k g_{k,t}(\xx,\xxi_t)\right] 
\end{equation}
Note that as in Theorem~\ref{thm:solution_convergence}, the value and solutions of the  CVaR constrained problem \eqref{eqn:cvar-approx} can be written as $s_\alpha^r$ times those of $O_\alpha^{\tt rel}$
To complete the proof, we demonstrate that the optimal value and solutions of \eqref{eqn:Oalpha} converge to $cv^*$ and $c\mathcal X^*$ respectively, in the sense defined in Theorem~\ref{thm:solution_convergence}. To this end, define the function $v_\alpha(\xx) = {\tt  VaR}_{1-\alpha}\left[\max_k \eta_k g_{k,t}(\xx,\xxi_t)\right]$ and note that
\begin{align}\label{eqn:CVaR_representation}
    J_\alpha(\xx) = v_\alpha(\xx) + \alpha^{-1}E\left[ \max_{k}\eta_k g_{k,t}(\xx,\xxi_t) - v_\alpha(\xx)\right]^+
\end{align}

\noindent \textbf{(i) Assumption~$(\mathscr{L})$ holds: } 
We demonstrate that $J_\alpha(\xx) \sim v_\alpha(\xx)$ uniformly over compact sets. 
first To this end, note that by definition for all $\varepsilon>0$ and $\xx\in \mathcal X$, $J_\alpha(\xx) \geq v_\alpha(\xx)$. We therefore prove a matching upper bound. To this end, it suffices to show that
\[
E\left[\max_k \eta_k g_{k,t}(\xx,\xxi_t) - v_\alpha(\xx)\right]^+=o(\alpha)
\]
Fix $\varepsilon>0$, and decompose the above expression as
\begin{align}\label{eqn:decompose_expc}
    E\left[\max_k \eta_k g_{k,t}(\xx,\xxi_t) - v_\alpha(\xx)\right]^+&\leq E\left[(\max_k \eta_k g_{k,t}(\xx,\xxi_t) - v_\alpha(\xx))^+ ; \psi_\alpha (\xx,\xxi_t)\leq \varepsilon\right]\nonumber \\
    &+ E\left[\max_k \eta_k g_{k,t}(\xx,\xxi_t) ; \psi_\alpha (\xx,\xxi_t)> \varepsilon\right] 
\end{align}
where 
\[
\psi_\alpha(\xx,\xxi_t) = \max_{k}\eta_k g_{k,t}(\xx,\xxi_t) - {v_\alpha(\xx)}.
\]
Note that the first term above can be bounded by $\varepsilon \alpha $. For the second term note that as a result of the continuous convergence of $g_{k,t}$
\[
\max_{k}\eta_k g_{k,t}(\xx,\zz) \to \max_{k}\eta_k g^*_k(\xx,\zz), \text{ uniformly over compact subsets of $\mathcal X$ }
\]
This suggests that whenever $\xx_t\to \xx$, 
\begin{align*}
    \max_{k}\eta_k g_{k,t}(\xx_t,\zz) &= \max_{k}\eta_k g_{k,t}(\xx_t,\hat\zz\|\zz\|)\\
    &= \max_{k}g^*_{k}(\xx,\hat \zz)\|\zz\|^{k}(1+o(1))
\end{align*}
as $\|\zz\|\to\infty$. Consequently, we have that whenever $\|\zz\|$ is large enough,
\begin{align*}
    \log  \max_{k}\eta_k g_{k,t}(\xx,\zz)  &\leq 2k\log \|\zz\| + \log \max_k g_k^*(\xx,\hat \zz)\\
    & \leq\varepsilon \|\zz\|^{\gamma+d} \text{ uniformly over $\xx$ in compact sets}
\end{align*}
Now, write the second term of \eqref{eqn:decompose_expc} as
\[
E\left[\max_k \eta_k g_{k,t}(\xx,\xxi_t) ; \psi_\alpha (\xx,\xxi_t)> \varepsilon\right]   \leq \exp\left(\log(g_\infty) \right) \mathbb P\left[\psi_{\alpha}(\xx,\xxi_t) > \varepsilon  \right]
\]
where $g_\infty = \sup_{k,\pp\in \mathcal S^{d-1}, \xx\in K} g_k^*(\xx,\pp)<\infty$. Use Proposition~\ref{prop:prob-convergence_LT} to obtain that uniformly over $\xx$ in compact sets, with $u = u^*(\xx) + \varepsilon$
\begin{align*}
    \log \mathbb P\left[\max_{k} \eta_k g_{k,t}(\xx,\xxi_t) > u\right] &\leq  \log \mathbb P\left[\max_{k}  g_{k,t}(\xx,\xxi_t) > u\right]  \text{ since }\eta_k\in(0,1)\\
    & \sim (w(\xx, u^*(\xx)+\varepsilon))^{r/\gamma} \log\alpha \\
    & \sim (1+\varepsilon)^{r/\gamma}\log \alpha 
\end{align*}
where the last step above follows upon noting that at $u^*(\xx)$, by definition, $w(\xx,u(\xx)) =1$, and that as $u$ increases, so does $w^*(\xx,u)$. Conclude from the above that, 
\[
E\left[\max_k \eta_k g_{k,t}(\xx,\xxi_t) ; \psi_\alpha (\xx,\xxi_t)> \varepsilon\right]  = O(\alpha^{1+\varepsilon}).
\]
Plug this observation in \eqref{eqn:decompose_expc} to note that 
\[
 E\left[\max_k \eta_k g_{k,t}(\xx,\xxi_t) - v_\alpha(\xx)\right]^+ \leq \alpha \varepsilon + O(\alpha^{1+\varepsilon})
\]
Since $\varepsilon$ above was arbitrary we have that 
\[
\alpha^{-1} E\left[\max_k \eta_k g_{k,t}(\xx,\xxi_t) - v_\alpha(\xx)\right] = o(1),
\]
Now apply Lemma~\ref{lem:var_asymptotic} to further infer that $C_\alpha(\xx) \sim u^*(\xx) $/ Following the proof of Theorem~\ref{thm:solution_convergence}, this  implies that any optimal solutions $\{\xx_\alpha^*: \alpha>0\}$ of the $\Dapprox$ satisfies $d(s_\alpha^{-r}\xx_\alpha^*,\mathcal X^*_0) \to 0$, where  $\mathcal X^*_0 = \arg\min\{c(\xx) : \max_k \eta_k g_k^*(\xx) \geq 0\}$. Noting that 
\[
\arg\min\{c(\xx) : \max_k \eta_k g_k^*(\xx) \geq 0\} = \arg\min \{c(\xx) : \max_k g_k^*(\xx) \geq 0\} = \mathcal Y^*
\]
concludes the proof.

