\noindent \textbf{Proof of Lemma~\ref{lem:line-search-properties}:} 
\textbf{a) }Note that the cost $c(\xx^{\tt app}_\alpha)$ is positive and homogeneous. Then,
$c(t^r \xx_{\alpha}^{\tt app}) = t^rc(\xx_{\alpha}^{\tt app}) $. 
Let us now consider two cases: first when $r>0$, the cost is positive,
and consequently, $c(\xx(t))$ is an increasing function of $t$. Next if $r<0$ then $c<0$, so as $t$ increases, once again $c(t^r\xx_\alpha^{\tt app})$ is increasing in $t$.

\noindent \textbf{b)} Note that $p(\xx_{\alpha}^{\tt app})\leq \alpha$, since $\xx_{\alpha}^{\tt app}$ is feasible to the safe approximation. Consequently, the infimisation problem defining $t_\alpha$ has a feasible solution. Further, by definition, for all $t\geq t_\alpha$, one has that $p(t^r\xx_{\alpha}^{\tt app}) \leq \alpha$,  or that $\xx(t)$ is feasible to $\CCPalpha$.

\noindent \textbf{c) }Note that $p(\cdot)$ is a continuous function, and by definition, $p(\xx_{\alpha}^{\tt app}) < \alpha$. Owing to continuity, there then exists a $t_\alpha^{\prime}<1$ such that $p(\xx(t))< \alpha$ for all $t\in (t_\alpha^\prime,1]$. Therefore, $t_\alpha = \inf\{t\in [0,1]: p(\xx(t)) \leq \alpha\} <t_\alpha^\prime <1$.
From part \textbf{a)} it now follows that $c(\xx_\alpha^\prime) < c(\xx_\alpha^{\tt app})$.\qed


\noindent \textbf{Proof of Proposition~\ref{prop:Approx_alg_guarantees}: }Note that for any $s\in(0,1]$, 
\begin{align*}
    p(s\xx_{\alpha}^{\tt app}) &=\mathbb P\left(\max_k g_k(s^r\xx_{\alpha}^{\tt app},\xxi) >0 \right)\\
    & = \mathbb P\left(g_t(s^rt^{-r}\xx_\alpha^{\tt app}) >0 \right) \\
    & = \mathbb P\left(g_t(s^r\yy_t^*(1+o(1))) >0 \right)  \text{ for a suitable $\yy_t^*\in c\mathcal X$}
\end{align*}
The last statement above follows from Theorems~\ref{thm:convex_rel}-\ref{thm:bfi-approx}, where it is demonstrated that any sequence of solutions  $\xx_\alpha^{\tt app}$  of the relaxed problem satisfy
$d(s_\alpha^{-r} \xx_{\alpha}^{\tt app},c\mathcal X^*) \to0 $ and therefore, $ t^r\xx_{\alpha}^{\tt app} = \yy_t^*+o(1)$ for some $\yy_t^*\in c\mathcal X$. Using the above observation, note that the minimization problem in Algorithm~\ref{algo:Vanish_Regret} can be re-cast as
\begin{equation}\label{eqn:t-alpha-value}
    t_\alpha = \inf\left\{s\in[0,1]: I_t(s\yy_t^*(1+(o(1))) \leq 1\right\}
\end{equation}
where $I_t$ is as defined in the proof of Theorem~\ref{thm:solution_convergence}. 
% \begin{lemma}\label{lem:I_homogenity}
%     The function $I(\cdot)$ defined in \eqref{eqn:I_star_limit} satisfies $I(c\xx) = c^{-\gamma/r}I(\xx)$ for all $\xx$ and $c>0$.
% \end{lemma}
Define the function $w_t(s) =I_t(s\yy_t^*(1+(o(1))) $ and $w(s) = (cs)^{
-\gamma/r}$. 
Observe that with $\yy_t^*\in c\mathcal X^*$, one has that $I(\yy_t^*) = 1$.
Then, using the homogeneity of $I$ from Lemma~\ref{lem:I_homogenity}, note that whenever $\yy_t^*\in c\mathcal X$, $I(s\yy_t^*) =(cs)^{-\gamma/r} = w(s)$.
\[
|w_t(s_t) - w(s) |\leq |I_t(s_t\yy_t^*(1+o(1)) - I(s_t \yy_t^*(1+o(1)))| + |I(s_t \yy_t^*(1+o(1))) - w(s)| \leq \varepsilon
\]
for all $t$ sufficiently large. To see this, note that the convergence of $I_t\to\ I$ is uniform over compacts sets using Propositions~\ref{prop:prob-convergence_LT}-\ref{prop:prob-convergence_HT}. The first term above can therefore be made as small as desired. Further note that since $I$ is continuous (and therefore uniformly continuous on compact sets), the second term can also be made arbitrarily small. 
This suggests that $w_t\to w$ continuously, and following the proof of Theorem~\ref{thm:solution_convergence}, we have that the optimal value of \eqref{eqn:t-alpha-value} converges to 
\[
\inf\{s: (cs)^{-r/\gamma} \leq 1\} = 1/c
\]
Now, write $\xx_\alpha^\prime = t_\alpha^r\xx_{\alpha}^{\tt app} = c(1+o(1))\xx_{\alpha}^{\tt app}$. Using the homogeneity of the cost function $c(\cdot)$, we have that 
\[
\frac{c(\xx_\alpha^\prime) - v_\alpha^*}{v_{\alpha}^*} = \frac{c^{-1}\times c v^*s_\alpha^{r}(1+o(1)) - v^* s_\alpha^r (1+o(1)) }{v^* s_\alpha^r (1+o(1))} \to 0
\]
as $\alpha\to 0.$ Finally, the decrease in suboptimality is given  by
\[
\lim_{\alpha\to 0} \frac{cv_\alpha^*s_\alpha(1+o(1))}{v^*s_\alpha^r} = c
\]
