\end{align}
Here, implication \textbf{(a)} above follows using the homogeneity of $c(\cdot)$ and the definition of $\tilde{\xx}_{N}$. 
Now, note that for every $\kappa>0$ and  $\omega\in\Omega_0$, there exists a large enough $n_0(\omega)$ such that for all $n\geq n_0(\omega)$, $d(\tilde {\xx}^{(N)},\mathcal Y^*) \leq \kappa$. Since $c(\cdot)$ is continuous and $\mathcal Y^*$ is compact, given any $\varepsilon>0$ we can choose a $\kappa$ so small that $c(\tilde {\xx}^{(N)}) < (1+\varepsilon)c(\mathcal Y^*)$. Then, we have from \eqref{eqn:cost_implications} that
\[
c\left(s_{\bar \alpha}^{-r}\frac{\xx}{1-\varepsilon^2}\right) \leq c(\mathcal Y^*) \text{ for all } n\geq n_0(\omega)
\]
This now implies that 
\[
I\left(s_{\bar \alpha}^{-r}\frac{\xx}{1-\varepsilon^2}\right)  \geq 1 \text{ for all } n\geq n_0(\omega)
\]
since the minimum value of the function $c(\cdot)$ over $I(\xx) \leq 1$ is $c(\mathcal Y^*)$. Using the homogeneity of $I(\cdot)$ from Lemma~\ref{lem:I_homogenity}, we further have that 
$I(\xx s_{\bar\alpha}^{-r}) > (1-\varepsilon^2)^{-\gamma/r}$. 
Since $I(\cdot)$ is homogeneous with order $-\gamma/r$ and $r>0$, the above also implies that $\xx s_{\bar \alpha}^{-r}$ lies in a compact set. If $\bar t = s_{\bar\alpha}$,
then as $\bar \alpha \to 0$, $I_{\bar t}\to I$ uniformly over compact sets. Then, since $I_{\bar t}(\xx) \geq I(\xx) + \varepsilon $ uniformly over $\xx$ in compact sets. This implies that 
\[
I_{\bar t}(s_{\bar \alpha}^{-r}\xx) > (1-\varepsilon^2)^{-\gamma/r} -\varepsilon \quad \text{ for all $n$ sufficiently large}
\]
% Further, recall that $ts_{\alpha_0} \sim s_{\alpha_0^t}$ if Assumption~($\mathscr{L}$) holds, and $s_{\alpha_0} \sim s_{\alpha_0/t}$  if Assumption~($\mathscr{H}$) holds

Now consider two cases:

\noindent \textbf{i) Assumption~($\mathscr{L}$) holds: } Recall that 
\[
I_{\bar t}(s_{\bar \alpha}^{-r}\xx) = -\frac{\log \bar F(s_{\bar\alpha}) }{\log p(\xx)} \implies \log p(\xx) \geq  \frac{\log \bar F(s_{\bar \alpha})}{(1-\varepsilon^2)^{-\gamma/r} -\varepsilon} \text{ for all } n>n_0
\]
Note now that $\log p(\hat \xx^{(N)})= \log  p(s_{\bar\alpha} \tilde \xx_N)$ where $d(\tilde \xx_N ,\mathcal Y^*) \to 0$ as $N\to\infty$. Consequently, we have that the tail sequence, $\{\tilde \xx_N: N>n_0\} $ lies in a compact set. Then, using the uniform convergence of log-probabilities from Proposition~\ref{prop:prob-convergence_LT},
\[
\left\vert\frac{-\log  p(s_{\bar\alpha}^{-r} \tilde \xx_N)}{\log \bar F(s_{\bar \alpha})} - I(\tilde \xx_N) \right\vert \leq \varepsilon \quad \text{ for all $n>n_1$ }. 
\]
Combining the above two displays, for all $n\geq \max\{n_0,n_1\}$
\[
\log p(\xx) \geq (1-\delta) \log p(\hat \xx^{(N)})
\]
where $\delta >0$. Note that by setting $t_N$ to be a sufficiently large constant, we can ensure the condition $p(\hat \xx^{(N)}) \sim aN^{-b}$ for $a>0$, $b\geq 1$. This concludes the proof in the light tailed case. 

\noindent \textbf{ii) Assumption~($\mathscr{H}$) holds:}
Here, we instead have that
\[
I_{\bar t}(s_{\bar \alpha}^{-r}\xx) = \frac{p(\xx)} {\bar F(s_{\bar\alpha}) }\implies p(\xx) \geq  \frac{ \bar F(s_{\bar \alpha})}{(1-\varepsilon^2)^{-\gamma/r} -\varepsilon} \text{ for all } n>n_0
\]
Note that from Proposition~\ref{prop:prob-convergence_HT}, that 
\[
\left\vert\frac{p(s_{\bar\alpha}^{-r} \tilde \xx_N)}{\bar F(s_{\bar \alpha})} - I(\tilde \xx_N) \right\vert \leq \varepsilon \quad \text{ for all $n>n_1$ }. 
\]
Combining the above two displays suggests that 
$p(\xx) \geq (1-\delta) p(\hat \xx^{(N)})$ for all $n\geq \max\{n_0,n_1\}$, which further suggests conclusion of the theorem.\qed


\noindent\textbf{Proof of Corollary~\ref{cor:P-Model-data-driven}: } First suppose that Assumption~($\mathscr{L}$) holds. 
Note the following for a arbitrary $\omega\in \Omega_0$.
\begin{align}\label{eqn:log_pn}
    \log p(\hat \xx^{(N)}) &= \log p(t^r s_{\alpha_0}^r \tilde \xx_N) = \log p(s_{\bar \alpha}^r \tilde \xx_N)\nonumber\\
    & = \lambda(s_{\bar \alpha}) I(\tilde \xx_N) (1+o(1)) = \lambda(s_{\bar \alpha}) I(\mathcal Y^*)(1+o(1)) \nonumber\\
    & = \lambda(s_{\bar \alpha}(1+o(1))) \text{ as $N\to\infty$}.
\end{align}
Next, note that from Theorem~\ref{thm:solution_convergence}, $t^rv_{\alpha_0}^* = (ts_{\alpha_0}^r v^*(1+o(1)))$. Then, write $\nu^*(t^rv_{\alpha_0}^*) $ as 
\[
\min_{\xx\in \mathcal X} \log p(\xx) \quad  \text{ s.t } \quad  c(\xx) \leq s_{\bar \alpha}^r v^*(1+o(1)).
\]
Use the homogeneity of $c(\cdot)$ and change variables to $\yy = s_{\bar\alpha}^{-r}(1+o(1)) \xx$ to reduce the above problem to
\[
\min_{\yy\in \mathcal X} \log p(s_{\bar\alpha}^{-r}\yy)  : c(\yy)\leq v^*
\]
Now, recall that from Proposition~\ref{prop:solution-set-convergence}, $\log p(s_{\alpha_0}^{-r}\yy) \sim -\lambda(s_{\alpha_0})[I(\yy)]^{-1}$. Therefore, an application of \cite{bonnans2013perturbation}, Proposition 4.4 yields that 
\[
\nu^*(t^rv_{\alpha_0}^*) \sim -\lambda(s_{\alpha_0}) \  \inf\{I(\xx) : c(\xx ) \leq 1\} \sim -\lambda(s_{\alpha_0})
\]
where the last asymptotic above follows from Lemma~\ref{lem:I_value}. Combining the above display with \eqref{eqn:log_pn} completes the proof for the light tailed case. 

If instead Assumption~($\mathscr{H}$) holds. Then, instead of \eqref{eqn:log_pn}, we have that $p(\hat \xx^{(N)}) =\lambda(s_{\bar \alpha})(1+o(1))$. Further, one has that $\nu^*(B)= \log (\mu^*(B))$ where  
\[
\mu^*(B) = \inf\{p(\xx) : c(\xx)\leq B\}
\]
Repeating the above steps,
$\mu^*(t^r v_{\alpha_0}^*) \sim \lambda(s_{\bar\alpha})$. Consequently, $\log p(\hat \xx^{(N)}) \sim \mu^*(t^r v_{\alpha_0}^*)$ as $N\to\infty$. Since $\omega\in \Omega_0$ was arbitrary, all the above asymptotics hold almost surely.\qed
