\noindent\textbf{Proof of Proposition~\ref{prop:ldp}: }  A sufficient
condition (see \cite{dembo2009large}, Theorem 4.1.11) to verify the existence
of LDP is to show that $\{\xxi_t:t\geq 1\}$ is exponentially tight, and that for all $\xx$, 
\begin{equation}\label{eqn:LDP-Equivalent}
-\varphi^*(\xx) = \inf_{\delta>0} \limsup_{t\to\infty} \frac{1}{t}\log\Prob\left( {\xxi}_{t} \in B_{\delta}(\xx)\right) = \inf_{\delta>0} \liminf_{t\to\infty} \frac{1}{t}\log\Prob\left( {\xxi_t} \in B_{\delta}(\xx)\right).
\end{equation}
Fix any $\varepsilon, M \in (0,\infty)$ and $\xx \in (0,M)^d.$ Since
$f_{\xxi}(\yy) = \exp(-\varphi(\yy)),$
\begin{align*}
  \Prob(\xxi_t \in B_{\delta}(\xx))
  = \int_{\xxi/g(t)\in B_{\delta}(\xx)}\exp(-\varphi(\yy))d\yy
  % = t^d \int_{\zz\in B_{\delta} (\xx)} f_{\YY}(t\zz) d\zz
    = [g(t)]^d \int_{\zz\in B_{\delta} (\xx)}  \e^{-\varphi(g(t)\zz)} d\zz.
\end{align*}

\noindent \textbf{Case (i): $\xx\not\in \mathcal E$: } Since $\mathcal E$ is closed, there exists a $\delta_1$ such that for all $\delta<\delta_1$, $B_{\delta}(\xx) \cap \mathcal E  = \emptyset$. Further,  since $\mathcal E$ is a cone, if $\xxi$ is supported on $\mathcal E$, so is $\xxi_t$ for all $t$. 
Consequently, for all $\delta<\delta_1$,  we have that $\mathbb P[\xxi_t\in   B_{\delta}(\xx)] = 0$, and \eqref{eqn:LDP-Equivalent} holds.

\noindent \textbf{Case (ii): $\xx\in\mathcal E$: } Recall that Assumption ($\mathscr{L}$) implies the following uniform
convergence over compact subsets of $\mathcal E$ not containing the origin: 
\begin{equation}
  \label{eqn:UC-expo}
n^{-1}\varphi(g(n)\xx) \xrightarrow{n\to\infty} \varphi^*(\xx).
\end{equation}
Due to this local uniform convergence and the continuity of $\varphi^*$, there
exist $\delta_0,t_0 \in (0,\infty)$ such that,
\begin{align*}
%  \label{eqn:U-C}
  \left\vert \frac{\varphi(g(t)\zz)}{t} - \varphi^*(\xx)  \right\vert \leq  \left\vert \frac{\varphi(g(t)\zz)}{t} - \varphi^*(\zz)\right\vert + \left\vert \varphi^*(\zz) - \varphi^*(\xx)\right\vert \leq \varepsilon/2, \textrm{ for all } \zz\in B_{\delta}(\xx)\cap \mathcal E
\end{align*}
whenever $t > t_0,$ $\delta < \delta_0$.
% Choose $\delta$ small and $t>t_0$ large enough,
% such that \eqref{eqn:U-C} is satisfied, and the set $B_{\delta}(\xx)$
% does not contain the origin.
% Then from \eqref{eqn:U-C}, 
% \[
% \varphi(t\zz) \in [t(I(\xx)-\epsilon), t(I(\xx) +\epsilon)],
% \]
% for $t>t_0$ and all $\zz$ in $B_{\delta}(\xx).$ Given any $\theta<1,$
% $\e^{-t^{\theta}\|\zz\|^{\theta}} \leq p(t\zz)\leq
% \e^{-t^{\theta}\|\zz\|^{\theta}},$ for all sufficiently large $t,$ as
% a consequence of ~(\ref{eqn:UC-expo}).  Also note that whenever
     %      $\delta$ is small enough, $\|\zz\| \leq M<\infty$.
Thus, given $\varepsilon, M$ and $\xx \in (0,M)^d,$ there exist
$\delta_0,t_0 \in (0,\infty)$ such that for all $t>t_0$ and
$\delta \in (0, \delta_0),$
\begin{equation}
  \label{eqn:Y-Bounds}
  \exp \left(-t(\varphi^*(\xx) +\varepsilon)\right) \leq f_{\xxi}(g(t)\zz) \leq
  \exp\left({-t(\varphi^*(\xx) -\varepsilon)}\right), \text{ uniformly over
    $\zz \in B_{\delta}(\xx) \cap \mathcal E ;$}
\end{equation}
% and consequently, 
Then 
%\begin{equation*}
%\label{eqn:Y_Upper}
\[
[g(t)]^d \mathrm{Vol}(B_{\delta}(\xx)\cap \mathcal E) \exp({-t(\varphi^*(\xx) + \epsilon)}) \leq
\Prob(\xxi_t \in B_{\delta}(\xx)) \leq [g(t)]^d
\mathrm{Vol}(B_{\delta}(\xx)) \exp({-t(\varphi^*(\xx) -\epsilon)}).
\]
%\end{equation*}
Since $\Prob(\xxi_t \in B_{\delta}(\xx)) $ is increasing in $\delta$
and these bounds hold for any $\delta < \delta_0,$
\[ - \varphi^*(\xx) - \epsilon \leq \inf_{\delta > 0}\liminf_{t\to\infty} \frac{1}{t} \log
  P(\xxi_t \in B_{\delta}(\xx)) \leq \inf_{\delta > 0} \limsup_{t\to\infty} \frac{1}{t} \log
  P(\xxi_t \in B_{\delta}(\xx)) \leq - \varphi^*(\xx) +\epsilon. 
\]
The last statement follows since 
$g\in \RV(1/\gamma)$, $\log g(t) = o(t)$ (see \cite{deHaan}, Proposition B.1.9).
Since the choices $\varepsilon, M \in (0,\infty)$ are arbitrary,
(\ref{eqn:LDP-Equivalent}) holds.

\noindent \textbf{Step 2: Prove exponential tightess: }To conclude, we demonstrate that  given $M>0$, there exists $\alpha=\alpha(M)$  such that $\limsup_n n^{-1}\log \mathbb P(\xxi_n\in B_\alpha^c) <-M$. Note that the hazard function of the radius $R=\|\xxi\|$ is
\begin{equation}\label{eqn:R_density}
    \Lambda_R(t) = -\log \left\{\int_{r\geq t,\pphi} r^{d-1}\exp(-\varphi(r\pphi)) drd\pphi\right\}
\end{equation}
Under Assumption ($\mathscr{L}$),
as $n\to\infty$, $\varphi(g(n)\xx) = n\varphi^*(\xx)(1+\varepsilon(n,\xx))$, where for any compact set $\mathcal K\subseteq \mathcal E$,
$\sup_{t\geq n,\xx\in \mathcal K}|\varepsilon(n,\xx)| \to 0$ as $n\to\infty$.
with $n=\lambda(r)$ the integral in  \eqref{eqn:R_density} becomes 
\begin{equation*}
\int_{r\geq t,\pphi} r^{d-1}\exp(-\lambda(r) \varphi^*(\pphi)(1+\varepsilon(r,\pphi))) drd\pphi = 
\int_{p\geq g^{\leftarrow}(t),\pphi} [\lambda(p)]^{d-1}\exp(-p \varphi^*(\pphi)(1+\varepsilon(\lambda(p),\pphi))) dpd\pphi    
\end{equation*}
Recall that from Lemma~\ref{lem:RVs}, $\lambda \in \RV(\gamma)$. Therefore, as $t\to\infty$, $\log \lambda(t) = o(t)$  (see \cite{deHaan}, Proposition B.1.9). In addition for every $\delta_0>0$, there exists a $n_0$ such that for $n>n_0$, $|\sup_{\pphi,n\geq n_0}  \varepsilon(n,\pphi)| \leq \delta_0$. The previous two statements imply that for all sufficiently large $t$,  
\begin{align*}
    \int_{p\geq\lambda(t),\pphi} [\lambda(p)]^{d-1}\exp(-p \varphi^*(\pphi)(1+\varepsilon(\lambda(p),\pphi))) dpd\pphi    &\leq \int_{p\geq \lambda(t)} \exp(-p \varphi^*(\pphi)(1-\delta_0))dpd\pphi\\
    &\leq {\tt Leb}(S^{d-1}) \exp(-\lambda(t) \inf_{\pphi\in \mathcal S^{d-1}\cap \mathcal E}\varphi^*(\pp))
\end{align*}
Consequently, 
\begin{equation}\label{eqn:LB_Lambda_R}
    \liminf_{t\to\infty} \frac{\Lambda_R(t)}{\lambda(t)} \geq \inf_{\pphi\in \mathcal S^{d-1}\cap \mathcal E} \varphi^*(\pphi)(1-\delta_0).
\end{equation}

To establish a lower bound, observe that the function $\varphi^*$ is continuous on $\mathcal E$. Let $\pphi_0$ be any point on $\mathcal S^{d-1}\cap \mathcal E$ where $\varphi^*$ attains a minimum. Then, fixing a $\delta_0$, there exists a neighbourhood of $\pphi_0$, call it $N_\delta(\pphi_0)$ 
such that $|\varphi^*(\pphi)-\varphi^*(\pphi_0)|\leq \delta_0$ for all $\pphi\in N_\delta(\pphi_0)$. Now, for all sufficiently large $t$, the integral 
\begin{align*}
    \int_{p\geq g^{\leftarrow}(t),\pphi} [\lambda(p)]^{d-1}\exp(-p \varphi^*(\pphi)(1+\varepsilon(\lambda(p),\pphi))) dpd\pphi    
    \end{align*}
    is lower bounded by
    \begin{align*}
    & \int_{p\geq \lambda(t), N_\delta(\pphi_0)} \exp(-p \varphi^*(\pphi_0)(1+\delta_0) dpd\pphi  \geq {\tt Leb}(N_\delta(\pphi_0)) \exp(-\lambda(t) (\delta_0+ (1+\delta_0) \inf_{\pphi\in \mathcal {S}^{d-1}\cap \mathcal E}\varphi^*(\pphi))
\end{align*}
Consequently, 
\begin{equation}\label{eqn:UB_Lambda_R}
    \liminf_{t\to\infty} \frac{\Lambda_R(t)}{\lambda(t)} \geq \inf_{\pphi\in \mathcal {S}^{d-1}\cap \mathcal E} \varphi^*(\pphi)(1+\delta_0) +\delta_0
\end{equation}
Since $\delta_0$ in \eqref{eqn:LB_Lambda_R}-\eqref{eqn:UB_Lambda_R} is arbitrary, conclude that $\Lambda_R(t) \sim \lambda(t) c_{\varphi^*}$,
where $\varphi^* = \inf_{\pphi\in \mathcal {S}^{d-1}\cap \mathcal E} \varphi^*(\pphi)$. To conclude the proof, note that 
\[
\log \mathbb P[\xxi/g(n) \in B_{\alpha}^c] = \log \mathbb P[R \geq g(n)\alpha]  \sim  - c_{\varphi^*} \lambda(g(n)\alpha)
\]
Since $\lambda\in \RV(\gamma)$, one has that $g\in \RV(1/\gamma)$ (see \cite{deHaan}, Proposition B.1.9). Now, further simplify the above expression as $n^{-1}\log \mathbb P[R \geq g(n)\alpha] \sim - c_{\varphi^*} \alpha^{1/\gamma} $
and thus,
\[
\limsup_{n\to\infty} \log n^{-1}\mathbb P[\xxi/g(n) \in B_{\alpha}^c] \leq - c_{\varphi^*} \alpha^{1/\gamma}.
\]
Set $\alpha = (M/c_{\varphi^*})^\gamma$ above to complete the proof.
\qed 


\noindent \textbf{Proof of Proposition~\ref{thm:HTT_RV}: }
Note that since $0\not\in A$, $A\subset B_{\varepsilon}^c$ for some $\varepsilon>0$. Then \cite{Resnickbook}, Proposition 5.20, implies that
\[
\int_{\zz\in A}t^{d}f_{\xxi}(t\zz)d\zz \sim \bar \lambda(t) \nu(A)
\]
Next, observe that $\xxi/t$ has a density equal to $f_{\xxi/t}(\zz) = t^{d}f_{\xxi}(t\zz)$. Substituting this expression above implies that $\mathbb P(\xxi/t \in A )\sim \lambda(t)\nu(A)$.\qed

\noindent \textbf{Proof of Lemma~\ref{lem:RVs}: }First suppose Assumption~($\mathscr{L}$)  holds. Note that 
\begin{align*}
    -\log f((tc)\zz) \lambda(tc) \varphi^*(\zz) \quad \text{ and } -\log f((tc)\zz) \sim \lambda(t) \varphi^*(c\zz).
\end{align*}
Taking limits of both of the above implies that
\[
\frac{\varphi^*(c\zz)}{\varphi^*(\zz)} = \lim_{t\to\infty}\frac{\lambda(ct)}{\lambda(t)} = c^{\gamma}
\]
 Next suppose Assumption~($\mathscr{H}$) holds. Then, 
\begin{align*}
    f((tc)\zz) \sim (ct)^{-d}\bar F(tc)  \varphi^*(\zz) \quad \text{ and } f((tc)\zz) \sim \bar t^{-d} F(t) \varphi^*(c\zz).
\end{align*}
Once again, taking limits,
\[
\frac{\varphi^*(c\zz)}{\varphi^*(\zz)} = \lim_{t\to\infty}\frac{(ct)^{-d}\bar F(ct)}{t^{-d}\bar F(t)} = c^{-(d+\gamma)}
\]
\qed

\noindent \textbf{Proof of Lemma~\ref{lem:I_homogenity}: }
Note that under Assumption~\ref{assume:constraint-functions-cvar}, we have that for every $s>0$
\begin{align}\label{eqn:g_homogenity}
    g(s^r\xx,s\zz) &= \lim_{t\to\infty} t^{-k}\max_k g_{k,t}((ts)^r\xx,(ts)\zz) \nonumber\\
    &=(ts)^{-k} s^k\lim_{t\to\infty}\max_{k}g_{k,t}((ts)^r\xx,(ts)\zz) = s^{-\rho}g^*(\xx,\zz) 
\end{align}
We prove Lemma~\ref{lem:I_homogenity} in two parts. First suppose that Assumption~($\mathscr{L}$) holds, and 
\[
I(\xx) = \inf\left\{\varphi^*(\zz) : g^*(\xx,\zz) \geq 0\right\}^{-1}
\]
Then
\begin{align*}
 I(c^r\xx) &=    \inf\left\{\varphi^*(\zz) : g^*(c\xx,\zz) \geq 0\right\}^{-1} = c^{-\gamma} \inf\left\{\varphi^*(\zz/c) : g^*(c^r\xx,c(\zz/c)) \geq 0\right\}^{-1} \text{ using Lemma~\ref{lem:RVs}}\\
 & = c^{-\gamma} \inf\left\{\varphi^*(\pp) : g^*(c^r\xx,c\pp) \geq 0\right\}^{-1} \text{ setting $\zz/c=\pp$}\\
 &=c^{-\gamma} \inf\{\varphi^*(\pp) : g^*(\xx,\pp) \geq 0\} \text{ from \eqref{eqn:g_homogenity}}
\end{align*}
Note that the last infimum above equals $I(\xx)$. Then, $I(c\xx) = c^{-\gamma/r}I(\xx)$. Next, suppose that Assumption~($\mathscr{H}$) holds. Then, recall that 
\[
I(\xx)  = \int_{g^*(\xx,\zz) \geq 0}\varphi^*(\zz) d\zz
\]
Then,
\begin{align*}
I(c^r\xx) &= \int_{g(c^r\xx,\zz) \geq 0}\varphi^*(\zz) d\zz  = \int_{g(c^r\xx,c\pp) \geq 0} c^d\varphi^*(c\pp)d\pp \quad \text{ setting } \zz =c\pp\\
& = \int_{g(\xx,\pp)\geq 0} c^{-(\gamma+d)+d}\varphi^*(\pp) = c^{-\gamma}I(\xx)
\end{align*}
The result for heavy tails now follows.\qed

