\section{Introduction}\label{sec:Intro}
% --------------------------------------------------------------------------

A \emph{partition} of a positive integer $k$ is a nonincreasing sequence of positive integers
\[
	\lambda = (\lambda_1, \lambda_2, \dots, \lambda_r)
\]
such that the sum of the parts is $k$. We write this as $\lambda \vdash k$. Equivalently, a partition can be expressed in frequency notation as $\lambda = (1^{m_1}, \dots, k^{m_k}) \vdash k$, where each $m_j \ge 0$ denotes the multiplicity of the part $j$. The \emph{length} of $\lambda$ is $\ell(\lambda) \coloneqq m_1 + \cdots + m_k$. For each $\lambda = (1^{m_1}, \dots, k^{m_k}) \vdash k$, we associate the monomial
\[
	X_\lambda \coloneqq \prod_{j=1}^k X_j^{m_j}.
\]
To introduce the notion of partition traces, let $\phi: \mathcal{P} \to \C$ be a map on the set $\mathcal{P}$ of all partitions. For each positive integer $k$, the \emph{partition trace} of $\phi$ is defined by
\[
	\mathrm{Tr}_k(\phi; X_1, \dots, X_k) \coloneqq \sum_{\lambda \vdash k} \phi(\lambda) X_\lambda.
\]
For instance, when $\phi$ is the constant map $\phi(\lambda) = 1$, the trace $\mathrm{Tr}_4(1; X_1, \dots, X_4)$ is given by
\[
	\mathrm{Tr}_4(1; X_1, X_2, X_3, X_4) = X_4 + X_3 X_1 + X_2^2 + X_2 X_1^2 + X_1^4.
\]

A particularly interesting case arises when each $X_j$ is specialized to the Eisenstein series $E_{2j}(q)$. The resulting series, called the \emph{traces of partition Eisenstein series}, have been studied in several recent papers. Here, the \emph{Eisenstein series} $E_{2k}(q)$ is defined by
\[
	E_{2k}(q) \coloneqq 1 - \frac{4k}{B_{2k}} \sum_{n=1}^\infty \sigma_{2k-1}(n) q^n,
\]
where $B_k$ is the $k$-th Bernoulli number (with $B_1 = 1/2$, to be used later), and $\sigma_{2k-1}(n) \coloneqq \sum_{d \mid n} d^{2k-1}$ is the usual divisor sum. 
As a representative example, Amdeberhan--Ono--Singh~\cite{AmdeberhanOnoSingh2024-pre} studied the following quotient recorded in Ramanujan's Lost Notebook~\cite[p.~369]{Ramanujan1988}:
\[
	V_{2k}(q) \coloneqq \frac{\sum_{n \in \Z} (-1)^n (6n+1)^{2k} q^{\frac{n(3n+1)}{2}}}{\sum_{n \in \Z} (-1)^n q^{\frac{n(3n+1)}{2}}},
\]
and obtained the following explicit formula that refines earlier results of Berndt--Yee~\cite{BerndtYee2003}, (see also~\cite[Chapter 14]{LostNoteII}).

\begin{theorem*}[Amdeberhan--Ono--Singh]
	For partitions $\lambda = (1^{m_1}, \dots, k^{m_k}) \vdash k$, we define
	\[
		\phi_V(\lambda) \coloneqq 4^k (2k)! \prod_{j=1}^k \frac{1}{m_j!} \left(\frac{(4^j - 1) B_{2j}}{(2j) (2j)!}\right)^{m_j}.
	\]
	Then we have
	\[
		V_{2k}(q) = \mathrm{Tr}_k(\phi_V; E_2(q), E_4(q), \dots, E_{2k}(q)).
	\]
\end{theorem*}

Historically, partition traces have appeared in a variety of contents, not limited to the case where each $X_j$ is evaluated at the Eisenstein series. As another example, let us revisit Lehmer's 1966 work~\cite{Lehmer1966} on cyclotomic polynomials. Let $\Phi_n(x)$ be the $n$-th cyclotomic polynomial. In this work, Lehmer showed that the higher derivatives of $\Phi_n(x)$ at $x=1$ can be expressed in terms of partition traces as follows. 

\begin{theorem*}[Lehmer]
	For partitions $\lambda = (1^{m_1}, \dots, k^{m_k}) \vdash k$, we define
	\[
		\phi_\Phi(\lambda) = k! \prod_{j=1}^k \frac{(-1)^{m_j}}{m_j! j^{m_j}}.
	\]
	Then, for $n \ge 2$, we have
	\[
		\frac{\Phi_n^{(k)}(1)}{\Phi_n(1)} = \mathrm{Tr}_k(\phi_\Phi; \varsigma_1(n), \varsigma_2(n), \dots, \varsigma_k(n)),
	\]
	where we define
	\[
		\varsigma_k(n) = -\frac{1}{(k-1)!} \sum_{m=1}^k \frac{B_m}{m} s(k,m) J_m(n),
	\]
	with $s(k, m)$ denoting the Stirling number of the first kind and $J_k(n)$ the Jordan totient function.
\end{theorem*}

The striking similarity between these two results is noteworthy and suggests the presence of a common and more fundamental underlying structure. The purpose of this article is to show that a wide range of results can be understood in a unified and transparent way through the classical \emph{Fa\`{a} di Bruno formula}. 

Roughly speaking, Fa\`{a} di Bruno's formula provides an explicit expression for the derivative of a composite function. We refer the reader to \cite{Johnson2002, Craik2005} for the historical background and detailed proofs, as well as the recent article~\cite{Sullivan2022}. To be precise, we introduce the (complete) \emph{Bell polynomial} $\scB_k(X_1, \dots, X_k) \in \Z[X_1, \dots, X_k]$, defined by the generating function
\begin{align}\label{def:Bell-polynomial}
	\sum_{k=0}^\infty \scB_k(X_1, \dots, X_k) \frac{t^k}{k!} = \prod_{j=1}^\infty \exp \left(X_j \frac{t^j}{j!}\right).
\end{align}
The first few examples are
\begin{align*}
	\scB_1(X_1) &= X_1,\\
	\scB_2(X_1, X_2) &= X_2 + X_1^2,\\
	\scB_3(X_1, X_2, X_3) &= X_3 + 3X_2 X_1 + X_1^3,\\
	\scB_4(X_1, X_2, X_3, X_4) &= X_4 + 4X_3 X_1 + 3X_2^2 + 6X_2 X_1^2 + X_1^4.
\end{align*}
It is easy to see that Bell polynomials can be expressed via partition traces:
\[
	\scB_k(X_1, \dots, X_k) = \mathrm{Tr}_k(\phi_\mathrm{B}; X_1, \dots, X_k),
\]
where we set
\[
	\phi_\mathrm{B}(\lambda) = k! \prod_{j=1}^k \frac{1}{m_j! (j!)^{m_j}}.
\]

\begin{theorem}[Fa\`{a} di Bruno's formula]
	Let $k$ be a positive integer. Suppose $f(x), g(x)$, and $h(x)$ are functions with all necessary derivatives defined. For partitions $\lambda = (1^{m_1}, \dots, k^{m_k}) \vdash k$, we define
	\[
		\phi_\mathrm{F}(\lambda) = k! f^{(\ell(\lambda))}(g(x)) \prod_{j=1}^k \frac{1}{m_j! (j!)^{m_j}}.
	\]
	Then we have
	\begin{align*}
		\frac{\dd^k}{\dd x^k} f(g(x)) &= \mathrm{Tr}_k(\phi_\mathrm{F}; g^{(1)}(x), g^{(2)}(x), \dots, g^{(k)}(x)).
	\end{align*}
	In particular, by applying this formula with $f(x) = \exp(x)$ and $g(x) = \log h(x)$, we obtain
	\[
		\frac{h^{(k)}(x)}{h(x)} = \scB_k ((\log h)^{(1)}(x), (\log h)^{(2)}(x), \dots, (\log h)^{(k)}(x)).
	\]
\end{theorem}

The observation that Fa\`{a} di Bruno's formula can be applied to derive Lehmer's theorem is due to Herrera-Poyatos and Moree~\cite{HerreraMoree2021}. Indeed, it is easy to see that
\[
	\lim_{x \to 1} \frac{\dd^j}{\dd x^j} \log \Phi_n(x) = -\sum_{\substack{0 < k < n \\ (k, n) = 1}} \frac{ (j-1)!}{(e^{2\pi ik/n} - 1)^j},
\]
which matches $-(j-1)! \varsigma_j(n)$ as shown in \cite[Theorem 2]{Lehmer1966}. Therefore, Fa\`{a} di Bruno's formula implies that
\begin{align*}
	\frac{\Phi_n^{(k)}(1)}{\Phi_n(1)} &= \scB_k(-\varsigma_1(n), \dots, -(k-1)! \varsigma_k(n))\\
		&= \mathrm{Tr}_k(\phi_\Phi; \varsigma_1(n), \dots, \varsigma_k(n)).
\end{align*}

In the following sections, we provide further reinterpretations of the theorem of Amdeberhan--Ono--Singh, as well as several results on MacMahon's partition functions, their generalizations, and reciprocal sums of parts in integer partitions, all viewed through the lens of the Fa\`{a} di Bruno formula.

