\section{Amdeberhan--Ono--Singh's theorem}
% --------------------------------------------------------------------------

First, we reinterpret the original proof by Amdeberhan--Ono--Singh~\cite{AmdeberhanOnoSingh2024-pre} using Fa\`{a} di Bruno's formula. By Euler's pentagonal number theorem, we have
\[
	\eta(\tau) \coloneqq q^{1/24} \prod_{m=1}^\infty (1-q^m) = q^{\frac{1}{24}} \sum_{n \in \Z} (-1)^n q^{\frac{n(3n+1)}{2}} = \sum_{n \in \Z} (-1)^n q^{\frac{(6n+1)^2}{24}},
\]
where $q = e^{2\pi i\tau}$. Applying Fa\`{a} di Bruno's formula with respect to $\tau$, we obtain
\[
	\left(\frac{2\pi i}{24}\right)^k V_{2k}(q) = \frac{\eta^{(k)}(\tau)}{\eta(\tau)} = \scB_k( (\log \eta)^{(1)}(\tau), \dots, (\log \eta)^{(k)}(\tau)).
\]
Since
\[
	\frac{\dd}{\dd \tau} \log \eta(\tau) = \frac{2\pi i}{24} E_2(q)
\]
and the ring $\C[E_2(q), E_4(q), E_6(q)]$ is closed under the differentiation by the Ramanujan's identities:
\[
	\frac{1}{2\pi i} \frac{\dd E_2}{\dd \tau} = \frac{E_2^2 - E_4}{12}, \qquad \frac{1}{2\pi i} \frac{\dd E_4}{\dd \tau} = \frac{E_2 E_4 - E_6}{3}, \qquad \frac{1}{2\pi i} \frac{\dd E_6}{\dd \tau} = \frac{E_2 E_6 - E_4^2}{2},
\]
it follows that
\[
	V_{2k}(q) \in \C[E_2(q), E_4(q), E_6(q)],
\]
recovering the result by Berndt--Yee~\cite{BerndtYee2003}. While some additional argument is required to fully derive the polynomial $\phi_V(\lambda)$ of Amdeberhan--Ono--Singh, the above calculation already yields an explicit formula of similar type as follows.

\begin{theorem}\label{thm:V-even}
	For a positive integer $k$, we have
	\[
		V_{2k}(q) = 24^k \scB_k(F_1(q), F_2(q), \dots, F_k(q)),
	\]
	where we define $F_1(q) = \frac{1}{24} E_2(q)$, and for $j \ge 2$, 
	\[
		F_j(q) \coloneqq - \sum_{n=1}^\infty n^{j-1} \sigma_1(n) q^n.
	\]
\end{theorem}

Although our discussion so far focuses on the even-index case $V_{2k}(q)$, a natural generalization to all $k$, regardless of parity, emerges when viewed from the perspective of Jacobi forms. Indeed, by fully exploiting the Jacobi triple product, we can derive a similar result for
\[
	V_k(q) \coloneqq \frac{\sum_{n \in \Z} (-1)^n (6n+1)^k q^{\frac{n(3n+1)}{2}}}{\sum_{n \in \Z} (-1)^n q^{\frac{n(3n+1)}{2}}}.
\]
As observed by Amdeberhan--Griffin--Ono~\cite{AmdeberhanGriffinOno2025-pre}, the traces of partition Eisenstein series discussed here reflect a deeper structure arising from underlying Jacobi forms.

\begin{theorem}\label{thm:V-general}
	For a positive integer $k$, we have
	\[
		V_k(q) = 6^k \scB_k(G_1(q), G_2(q), \dots, G_k(q)),
	\]
	where we define
	\[
		G_1(q) = \frac{1}{6} + \sum_{n=1}^\infty \sum_{d \mid n} \left(\frac{-3}{d}\right) q^n,
	\]
	and for $j \ge 2$,
	\[
		G_j(q) = \begin{cases}
			\displaystyle{- \sum_{n=1}^\infty \sum_{\substack{d \mid n \\ n/d \not\equiv 0\ (3)}} d^{j-1} q^n} &\text{if $j$ is even},\\
			\displaystyle{\sum_{n=1}^\infty \sum_{d \mid n} \left(\frac{-3}{n/d}\right) d^{j-1} q^n} &\text{if $j \ge 3$ is odd},
		\end{cases}
	\]
	where $\left(\frac{\cdot}{\cdot}\right)$ is the Kronecker symbol.
\end{theorem}

\begin{proof}
	By applying Fa\`{a} di Bruno's formula to Jacobi's triple product
	\[
		\Theta_q(z) = \sum_{n \in \Z} (-1)^n q^{\frac{n(3n+1)}{2}} \zeta^{6n+1} = \zeta \prod_{m=1}^\infty (1- q^{3m}) (1-q^{3m-1}\zeta^6) (1-q^{3m-2} \zeta^{-6}),
	\]
	where $\zeta = e^{2\pi i z}$, we have
	\[
		(2\pi i)^k V_k(q) = \lim_{z \to 0} \frac{\Theta_q^{(k)} (z)}{\Theta_q(z)} = \scB_k((\log \Theta_q)^{(1)}(0), \dots, (\log \Theta_q)^{(k)}(0)).
	\]
	Using the infinite product expression, we find
	\[
		\frac{\dd}{\dd z} \log \Theta_q(z) = 2\pi i \bigg(1 - 6 \sum_{m, n \ge 1} q^{(3m-1)n} \zeta^{6n} + 6 \sum_{m, n \ge 1} q^{(3m-2)n} \zeta^{-6n} \bigg).
	\]
	By repeatedly differentiating this expression and then taking the limit $z \to 0$ (i.e., $\zeta \to 1$), we arrive at the desired result.
\end{proof}

For even $k$, \cref{thm:V-even} and \cref{thm:V-general} provide two different expressions for the same quantity. For example, in the case $k=2$, we have
\[
	V_2(q) = 36 (G_1(q)^2 + G_2(q)) = 24 F_1(q) = E_2(q).
\]

Finally, we note that a similar observation applies to another function,
\[
	U_{2k}(q) \coloneqq \frac{\sum_{n=0}^\infty (-1)^n (2n+1)^{2k+1} q^{\frac{n(n+1)}{2}}}{\sum_{n=0}^\infty (-1)^n (2n+1) q^{\frac{n(n+1)}{2}}},
\]
which was also studied by Amdeberhan--Ono--Singh~\cite{AmdeberhanOnoSingh2024-pre}. By focusing on the well-known identity
\[
	\sum_{n=0}^\infty (-1)^n (2n+1) q^{\frac{n(n+1)}{2}} = \prod_{m=1}^\infty (1-q^m)^3,
\]
the corresponding result follows in much the same way. Compared with \cref{thm:V-even}, this is a remarkably unified expression.

\begin{theorem}
	For a positive integer $k$, we have
	\[
		U_{2k}(q) = 8^k \scB_k(3F_1(q), 3F_2(q), \dots, 3F_k(q)),
	\]
	where $F_j(q)$ is defined as in \cref{thm:V-even}.
\end{theorem}

