\section{MacMahon's partition functions}
% --------------------------------------------------------------------------

In 1920, MacMahon~\cite{MacMahon1920} extended the classical divisor sums from the perspective of partition theory. For a positive integer $k$, \emph{MacMahon's partition function} $M_k(n)$ is defined by the generating series
\[
	A_k(q) \coloneqq \sum_{n=1}^\infty M_k(n) q^n = \sum_{0 < m_1 < m_2 < \cdots < m_k} \frac{q^{m_1 + m_2 + \cdots + m_k}}{(1-q^{m_1})^2 (1-q^{m_2})^2 \cdots (1-q^{m_k})^2}.
\]
A simple observation, essentially the same as one found in MacMahon's original work, shows that the following identity holds:
\[
	\mathcal{A}(X) \coloneqq 1 + \sum_{k=1}^\infty A_k(q) X^k = \prod_{m=1}^\infty \left(1 + \frac{q^m}{(1-q^m)^2} X\right).
\]
Applying the Fa\`{a} di Bruno formula to this identity at $X=0$, we obtain the following, which provides a new proof of the quasi-modularity of $A_k(q)$.

\begin{theorem}\label{thm:Ak-quasi}
	For a positive integer $k$, we have
	\[
		A_k(q) = \frac{1}{k!} \scB_k(H_1(q), H_2(q), \dots, H_k(q)),
	\]
	where
	\begin{align*}
		H_j(q) &= \frac{(-1)^{j-1}(j-1)!}{(2j-1)!} \sum_{l=1}^{2j} t(j,l) L_l(q),\\
		L_l(q) &= \sum_{n=1}^\infty \sigma_{l-1}(n) q^n,
	\end{align*}
	and $t(j,l) \in \Z$ are the central factorial numbers (see OEIS~\cite[A008955]{OEIS}) defined by
	\[
		\sum_{l=1}^{2j} t(j, l) x^{l-1} = \prod_{|i| < j} (x-i) = (2j-1)! \binom{x+j-1}{2j-1}.
	\]
\end{theorem}

\begin{proof}
	The infinite product expression implies that
	\[
		\frac{\dd}{\dd X} \log \mathcal{A}(X) = - \sum_{m=1}^\infty \sum_{n=1}^\infty (-1)^n \frac{q^{mn}}{(1-q^m)^{2n}} X^{n-1},
	\]
	and hence
	\[
		H_j(q) = \lim_{X \to 0} \frac{\dd^j}{\dd X^j} \log \mathcal{A}(X) = (-1)^{j-1} (j-1)!\sum_{m=1}^\infty \frac{q^{jm}}{(1-q^m)^{2j}}.
	\]
	Applying the binomial theorem, we find that
	\[
		\frac{q^{jm}}{(1-q^m)^{2j}} = \sum_{n=1}^\infty \binom{n+j-1}{2j-1} q^{mn} = \frac{1}{(2j-1)!} \sum_{n=1}^\infty \sum_{l=1}^{2j} t(j,l) n^{l-1} q^{mn},
	\]
	which leads to the desired result.
\end{proof}

\begin{corollary}
	For a positive integer $k$, we have $A_k(q) \in \Q[E_2(q), E_4(q), E_6(q)]$, that is, $A_k(q)$ is a quasi-modular form.
\end{corollary}

\begin{proof}
	Since $\prod_{|i| < j} (x-i)$ is an odd polynomial in $x$, it follows that $t(j,l) = 0$ whenever $l$ is odd. Therefore, $H_j(q) \in \Q[E_2(q), E_4(q), \dots, E_{2j}(q)]$. The fact that the polynomial ring $\Q[E_k(q): k \in 2\Z_{>0}]$ coincides with $\Q[E_2(q), E_4(q), E_6(q)]$ is a fundamental property of quasi-modualr forms (see, for example, Kaneko--Zagier~\cite{KanekoZagier1995}).
\end{proof}

The quasi-modularity of MacMahon's function $A_k(q)$ was originally proved by Andrews--Rose~\cite{AndrewsRose2013}, and an alternative proof based on an explicit generating function expression was later given by Bachmann~\cite{Bachmann2024}. Our proof may be seen as more classical in spirit, as it directly applies the Fa\`{a} di Bruno formula to MacMahon's original observation, followed by a straightforward use of the binomial theorem. 

We remark that Bachmann's explicit formula can be rewritten in the form
\[
	A_k(q) = \Lambda_k(L_2(q), L_4(q), \dots, L_{2k}(q)),
\]
where $\Lambda_k(X_1, \dots, X_k)$ is a polynomial defined as a slight modification of the Bell polynomial generating function \eqref{def:Bell-polynomial}, given by
\[
	\sum_{k=0}^\infty \Lambda_k(X_1, \dots, X_k) t^{2k} = \prod_{j=1}^\infty \exp \left(\frac{2(-1)^{j-1}}{(2j)!} \left(2 \arcsin \frac{t}{2}\right)^{2j} X_j \right).
\]
In joint work with Kang and Shin~\cite{KangMatsusakaShin2025}, we showed that this same polynomial $\Lambda_k$ also describes MacMahon's variants and the generalizations introduced by Rose~\cite{Rose2015}. This allowed us to prove quasi-modularity in a broader setting. The proof of \cref{thm:Ak-quasi} presented here applies equally well to Rose's generalized case. Moreover, in the same joint article with Kang and Shin, we suggested possible connections with Lehmer's theorem, as well as with related work by the author and Shibukawa~\cite{MatsusakaShibukawa2024}. In this context, the Fa\`{a} di Bruno formula seems to provide a natural explanation to these observations.

This method using Fa\`{a} di Bruno's formula is also applicable to another family of MacMahon-type functions recently introduced by Amdeberhan--Andrews--Tauraso~\cite{AmdeberhanAndrewsTauraso2025} and further studied by Nazaroglu--Pandey--Singh~\cite{NazarogluPandeySingh2025-pre}. For positive integers $k, t, r$, we define
\[
	A_{k,t,r}(a; q) \coloneqq \sum_{0 < m_1 < m_2 < \cdots < m_k} \frac{q^{r(m_1 + m_2 + \cdots + m_k)}}{(1+aq^{m_1} + q^{2m_1})^t \cdots (1+aq^{m_k} + q^{2m_k})^t}.
\]
While $a$ is treated as an integer in this context, the argument does not require it. We note that $A_{k,1,1}(-2; q) = A_k(q)$. Applying the Fa\`{a} di Bruno formula, we obtain the following.

\begin{theorem}
	For positive integers $k, t, r$, we have
	\[
		A_{k,t,r}(q) = \frac{1}{k!} \scB_k(H_{1,t,r}(a;q), H_{2,t,r}(a;q), \dots, H_{k,t,r}(a;q)),
	\]
	where we define
	\[
		H_{j,t,r}(a; q) = (-1)^{j-1} (j-1)! \sum_{m=1}^\infty \frac{q^{rjm}}{(1+aq^m+q^{2m})^{tj}}.
	\]
\end{theorem}

\begin{proof}
	The proof is entirely analogous to that of \cref{thm:Ak-quasi} and is therefore omitted.
\end{proof}

For example, the proof of quasi-modularity given by Nazaroglu--Pandey--Singh~\cite{NazarogluPandeySingh2025-pre} can be reorganized in the following way, by reducing the problem to the quasi-modularity of $H_{j,t,r}(a;q)$. 
This does not cover the full scope of their results, but we present one representative example here to illustrate the main idea. For the definition of quasi-modular forms and further details, we refer the reader to their article.

\begin{corollary}
	For positive integers $k, t$, and $a=1$, $A_{k,t,t}(1;q)$ is a quasi-modular form of level $3$.
\end{corollary}

\begin{proof}
	As shown in \cite[Section 3]{NazarogluPandeySingh2025-pre},
	\[
		\sum_{m=1}^\infty \frac{q^{tjm}}{(1+q^m+q^{2m})^{tj}}
	\]
	is a linear combination of $1, L_l(q), L_l(q^3)$, and 
	\[
		\sum_{n=1}^\infty \sum_{d \mid n} \left(\frac{-3}{d}\right) d^l q^n
	\]
	with even $l$. Hence, this is a quasi-modular form of level $3$, that is, the quasi-modularity of $A_{k,t,t}(1; q)$ follows.
\end{proof}

% --------------------------------------------------------------------------
\section{Reciprocal sums of parts in integer partitions}\label{sec:SRP}
% --------------------------------------------------------------------------

Finally, we conclude with some remarks on recent work by Byungchan Kim and Eunmi Kim~\cite{KimKim2025}, focusing on what the Fa\`{a} di Bruno formula reveals about their topic of study. For a positive integer $n$, let $\mathcal{D}_n$ denote the set of partitions $\lambda = (\lambda_1, \dots, \lambda_r) \vdash n$ into distinct parts, that is, $\lambda_i \neq \lambda_j$ whenever $i \neq j$. We define the map $\mathrm{srp}: \mathcal{D}_n \to \Q$ by 
\[
	\mathrm{srp}(\lambda) = \sum_{j=1}^{\ell(\lambda)} \frac{1}{\lambda_j}.
\]
Graham~\cite[Theorem 1]{Graham1963} proved that for $n > 77$, there exists a partition $\lambda \in \mathcal{D}_n$ such that $\mathrm{srp}(\lambda) = 1$. Following this result, they studied a more general family of moments defined by
\[
	s_k(n) \coloneqq \sum_{\lambda \in \mathcal{D}_n} \mathrm{srp}(\lambda)^k
\]
for positive integers $k$, and, in collaboration with Bringmann~\cite{BringmannKimKim2024-pre, BringmannKimKim2025-pre}, focused on their asymptotic behavior and modular aspects.

The main focus here is the generating function identity
\[
	\sum_{n=1}^\infty s_k(n) q^n = \lim_{\zeta \to 1} \left(\zeta \frac{\dd}{\dd \zeta}\right)^k \prod_{m=1}^\infty (1 + \zeta^{1/m} q^m)
\]
noted in~\cite{BringmannKimKim2024-pre}. They further introduced the functions
\[
	g_k(q) \coloneqq \sum_{n=1}^\infty \frac{1}{n^k} \sum_{d \mid n} (-1)^{d-1} d^{2k-1} q^n = \lim_{\zeta \to 1} \left(\zeta \frac{\dd}{\dd \zeta}\right)^k \sum_{m=1}^\infty \log(1+\zeta^{1/m} q^m)
\]
to establish that
\[
	\prod_{m=1}^\infty \frac{1}{1+q^m} \cdot \sum_{n=1}^\infty s_k(n) q^n \in \Z[g_1(q), g_2(q), \dots, g_k(q)].
\]
However, their proof followed an inductive structure, and as in the various examples discussed in the previous sections, the explicit description of the resulting polynomials was considered to be complicated. For these polynomials as well, an explicit formula can be derived immediately from the Fa\`{a} di Bruno formula.

\begin{theorem}
	For a positive integer $k$, we have
	\[
		\prod_{m=1}^\infty \frac{1}{1+q^m} \cdot \sum_{n=1}^\infty s_k(n) q^n = \scB_k(g_1(q), g_2(q), \dots, g_k(q)).
	\]
\end{theorem}

\begin{proof}
	Applying Fa\`{a} di Bruno's formula to
	\[
		\theta_q(z) = \prod_{m=1}^\infty (1+\zeta^{1/m} q^m)
	\]
	at $z = 0$ with $\zeta = e^{2\pi iz}$, and using the relation $\zeta \frac{\dd}{\dd \zeta} = \frac{1}{2\pi i} \frac{\dd}{\dd z}$, we obtain the desired identity.
\end{proof}


